60	fn run() -> Result<(), String> {
61	    let workspace_root = workspace_root()?;
62	    let images_dir = workspace_root.join("data/oxford-iiit-pet/images");
63	    if !images_dir.is_dir() {
64	        return Err(format!(
65	            "{} not found -- extract the Oxford-IIIT Pet tarball there first",
66	            images_dir.display()
67	        ));
68	    }
69	    let out_path = workspace_root.join("crates/mlpl-eval/data/pets_tiny.bin");
70	
71	    let (cats, dogs) = pick_files(&images_dir)?;
72	    if cats.len() < CATS_PER_CLASS {
73	        return Err(format!(
74	            "only {} cat files in {}, need {}",
75	            cats.len(),
76	            images_dir.display(),
77	            CATS_PER_CLASS
78	        ));
79	    }
80	    if dogs.len() < DOGS_PER_CLASS {
81	        return Err(format!(
82	            "only {} dog files in {}, need {}",
83	            dogs.len(),
84	            images_dir.display(),
85	            DOGS_PER_CLASS
86	        ));
87	    }
88	
89	    let mut picks: Vec<(PathBuf, u8)> = Vec::with_capacity(CATS_PER_CLASS + DOGS_PER_CLASS);
90	    for p in cats.iter().take(CATS_PER_CLASS) {
91	        picks.push((p.clone(), 0));
92	    }
93	    for p in dogs.iter().take(DOGS_PER_CLASS) {
94	        picks.push((p.clone(), 1));
95	    }
96	
97	    let mut y_bytes = Vec::with_capacity(picks.len());
98	    let mut names_buf: Vec<u8> = Vec::new();
99	    let mut x_bytes: Vec<u8> = Vec::with_capacity(picks.len() * 3 * TARGET_SIZE * TARGET_SIZE);
100	    for (idx, (path, label)) in picks.iter().enumerate() {
101	        let rgb_hwc = decode_and_resize_u8(path, TARGET_SIZE, TARGET_SIZE)
102	            .map_err(|e| format!("[{idx}] decode/resize {}: {e}", path.display()))?;
103	        if rgb_hwc.len() != 3 * TARGET_SIZE * TARGET_SIZE {
104	            return Err(format!(
105	                "[{idx}] {} resized to wrong size: got {} bytes",
106	                path.display(),
107	                rgb_hwc.len()
108	            ));
109	        }
110	        // HWC -> CHW
111	        let mut chw = vec![0u8; rgb_hwc.len()];
112	        for c in 0..3 {
113	            for y in 0..TARGET_SIZE {
114	                for x in 0..TARGET_SIZE {
115	                    let src = (y * TARGET_SIZE + x) * 3 + c;
116	                    let dst = c * TARGET_SIZE * TARGET_SIZE + y * TARGET_SIZE + x;
117	                    chw[dst] = rgb_hwc[src];
118	                }
119	            }
120	        }
121	        x_bytes.extend_from_slice(&chw);
122	        y_bytes.push(*label);
123	        let name = path
124	            .file_name()
125	            .and_then(|n| n.to_str())
126	            .ok_or_else(|| format!("[{idx}] non-utf8 filename"))?;
127	        names_buf.extend_from_slice(name.as_bytes());
128	        names_buf.push(0);
129	        if idx % 20 == 0 {
130	            println!("  {idx:>3} / {} ({})", picks.len(), name);
131	        }
132	    }
133	    let n = picks.len();
134	    let names_len =
135	        u32::try_from(names_buf.len()).map_err(|_| "name table exceeds u32".to_string())?;
136	
137	    let mut out = Vec::with_capacity(28 + n + 4 + names_buf.len() + x_bytes.len());
138	    out.extend_from_slice(MAGIC);
139	    out.extend_from_slice(&VERSION.to_le_bytes());
140	    out.extend_from_slice(&(n as u32).to_le_bytes());
141	    out.extend_from_slice(&3u32.to_le_bytes());
142	    out.extend_from_slice(&(TARGET_SIZE as u32).to_le_bytes());
143	    out.extend_from_slice(&(TARGET_SIZE as u32).to_le_bytes());
144	    out.extend_from_slice(&y_bytes);
145	    out.extend_from_slice(&names_len.to_le_bytes());
146	    out.extend_from_slice(&names_buf);
147	    out.extend_from_slice(&x_bytes);
148	
149	    fs::create_dir_all(out_path.parent().unwrap()).map_err(|e| format!("mkdir: {e}"))?;
150	    let mut f = fs::File::create(&out_path).map_err(|e| format!("create: {e}"))?;
151	    f.write_all(&out).map_err(|e| format!("write: {e}"))?;
152	    println!("wrote {} ({} bytes)", out_path.display(), out.len());
153	    Ok(())
154	}
