157	fn pick_files(images_dir: &std::path::Path) -> Result<(Vec<PathBuf>, Vec<PathBuf>), String> {
158	    use std::collections::BTreeMap;
159	    let mut all: Vec<PathBuf> = fs::read_dir(images_dir)
160	        .map_err(|e| format!("readdir {}: {e}", images_dir.display()))?
161	        .filter_map(Result::ok)
162	        .map(|e| e.path())
163	        .filter(|p| {
164	            p.extension()
165	                .and_then(|e| e.to_str())
166	                .map(|e| e.eq_ignore_ascii_case("jpg") || e.eq_ignore_ascii_case("jpeg"))
167	                .unwrap_or(false)
168	        })
169	        .collect();
170	    all.sort();
171	    // Group by breed (filename prefix up to the last `_`).
172	    // Breeds with a leading capital are cats; lowercase are dogs.
173	    let mut by_breed: BTreeMap<String, Vec<PathBuf>> = BTreeMap::new();
174	    for p in all {
175	        let Some(name) = p.file_name().and_then(|n| n.to_str()) else {
176	            continue;
177	        };
178	        let breed = name
179	            .rsplit_once('_')
180	            .map(|(b, _)| b.to_string())
181	            .unwrap_or_else(|| name.to_string());
182	        by_breed.entry(breed).or_default().push(p);
183	    }
184	    let mut cat_breeds: BTreeMap<String, Vec<PathBuf>> = BTreeMap::new();
185	    let mut dog_breeds: BTreeMap<String, Vec<PathBuf>> = BTreeMap::new();
186	    for (breed, files) in by_breed {
187	        let first = breed.chars().next().unwrap_or(' ');
188	        if first.is_ascii_uppercase() {
189	            cat_breeds.insert(breed, files);
190	        } else if first.is_ascii_lowercase() {
191	            dog_breeds.insert(breed, files);
192	        }
193	    }
194	    // Round-robin pick across breeds so the 100 per class
195	    // are spread evenly: one from each breed, then the
196	    // second from each, until we have enough.
197	    let cats = round_robin(&cat_breeds, CATS_PER_CLASS);
198	    let dogs = round_robin(&dog_breeds, DOGS_PER_CLASS);
199	    Ok((cats, dogs))
200	}
