109	/// Fused log-softmax + NLL forward pass. Scalar output.
110	///
111	/// `logits` is `[N, V]` (caller must pre-flatten `[B, T, V]` to
112	/// `[B*T, V]`); `targets` has length `N`. Stable via max-subtraction
113	/// inside the log-sum-exp.
114	pub(crate) fn cross_entropy_forward(
115	    logits: &mlpl_array::DenseArray,
116	    targets: &[usize],
117	) -> Result<mlpl_array::DenseArray, String> {
118	    let (n, v) = ce_split_rows_cols(logits)?;
119	    if targets.len() != n {
120	        return Err(format!(
121	            "cross_entropy: target length {} does not match logits rows {}",
122	            targets.len(),
123	            n
124	        ));
125	    }
126	    let data = logits.data();
127	    let mut total = 0.0;
128	    for (i, &t) in targets.iter().enumerate() {
129	        if t >= v {
130	            return Err(format!(
131	                "cross_entropy: target index {t} out of range for V={v}"
132	            ));
133	        }
134	        let row = &data[i * v..(i + 1) * v];
135	        let m = row.iter().copied().fold(f64::NEG_INFINITY, f64::max);
136	        let lse: f64 = m + row.iter().map(|x| (x - m).exp()).sum::<f64>().ln();
137	        total += lse - row[t];
138	    }
139	    Ok(mlpl_array::DenseArray::from_scalar(total / n as f64))
140	}
