142	/// Cross-entropy backward pass: returns `d loss / d logits` shaped like
143	/// `logits`, computed as `(softmax(logits) - one_hot(targets)) / N *
144	/// upstream_scalar`.
145	pub(crate) fn cross_entropy_backward(
146	    logits: &mlpl_array::DenseArray,
147	    targets: &[usize],
148	    upstream_scalar: f64,
149	) -> mlpl_array::DenseArray {
150	    let (n, v) = ce_split_rows_cols(logits).expect("forward validated shape");
151	    let data = logits.data();
152	    let mut out = vec![0.0; data.len()];
153	    let inv_n = 1.0 / n as f64;
154	    for (i, &t) in targets.iter().enumerate() {
155	        let row = &data[i * v..(i + 1) * v];
156	        let m = row.iter().copied().fold(f64::NEG_INFINITY, f64::max);
157	        let exps: Vec<f64> = row.iter().map(|x| (x - m).exp()).collect();
158	        let s: f64 = exps.iter().sum();
159	        for (j, e) in exps.iter().enumerate() {
160	            let p = e / s;
161	            let indicator = if j == t { 1.0 } else { 0.0 };
162	            out[i * v + j] = upstream_scalar * (p - indicator) * inv_n;
163	        }
164	    }
165	    mlpl_array::DenseArray::new(logits.shape().clone(), out).expect("shape preserved")
166	}
