168	fn ce_split_rows_cols(logits: &mlpl_array::DenseArray) -> Result<(usize, usize), String> {
169	    let dims = logits.shape().dims();
170	    match dims.len() {
171	        2 => Ok((dims[0], dims[1])),
172	        3 => Ok((dims[0] * dims[1], dims[2])),
173	        r => Err(format!(
174	            "cross_entropy: logits must be rank 2 or 3, got rank {r}"
175	        )),
