        } => {
            let grad = patchify_backward(&upstream, &orig_shape, patch_size);
            accumulate(&mut tape.nodes_mut()[parent.0].grad, grad);
        }
        NodeKind::Concat {
            left,
            right,
            axis,
            left_size,
        } => {
            let (ga, gb) = concat_backward(&upstream, axis, left_size);
            let mut nodes = tape.nodes_mut();
            accumulate(&mut nodes[left.0].grad, ga);
            accumulate(&mut nodes[right.0].grad, gb);
        }
    }
}

/// Scatter `[B, N, P*P*C]` gradient back to `[B, C, H, W]`
/// image space. Each output element of patchify corresponds
/// to exactly one input element, so the backward is just the
/// inverse indexing -- no accumulation across positions.
fn patchify_backward(upstream: &DenseArray, orig_shape: &Shape, p: usize) -> DenseArray {
    let dims = orig_shape.dims();
    let (b, c, h, w) = (dims[0], dims[1], dims[2], dims[3]);
    let nh = h / p;
    let nw = w / p;
    let n_patches = nh * nw;
    let patch_len = p * p * c;
    let up = upstream.data();
    let mut out = vec![0.0; b * c * h * w];
    for b_i in 0..b {
        for i in 0..nh {
            for j in 0..nw {
                let n = i * nw + j;
                for c_i in 0..c {
                    for dy in 0..p {
                        for dx in 0..p {
                            let src_y = i * p + dy;
                            let src_x = j * p + dx;
                            let dst_idx = ((b_i * c + c_i) * h + src_y) * w + src_x;
                            let src_idx = (b_i * n_patches + n) * patch_len
                                + c_i * p * p
                                + dy * p
                                + dx;
                            out[dst_idx] = up[src_idx];
                        }
                    }
                }
            }
        }
    }
    DenseArray::new(orig_shape.clone(), out).expect("shape")
}

/// Split a concat upstream gradient at `left_size` along
/// `axis`. Supports axis 0 (whole-array slice) and axis 1
/// (per-row interleaved slice).
fn concat_backward(
    upstream: &DenseArray,
    axis: usize,
    left_size: usize,
) -> (DenseArray, DenseArray) {
    let dims = upstream.shape().dims();
    let total = dims[axis];
    let right_size = total - left_size;
    let mut left_dims = dims.to_vec();
    left_dims[axis] = left_size;
    let mut right_dims = dims.to_vec();
    right_dims[axis] = right_size;
    let up = upstream.data();
    let (left_data, right_data) = if axis == 0 {
        let per_a: usize = dims[1..].iter().product::<usize>().max(1) * left_size;
        let per_b: usize = dims[1..].iter().product::<usize>().max(1) * right_size;
        (up[..per_a].to_vec(), up[per_a..per_a + per_b].to_vec())
    } else {
        let trailing: usize = dims[2..].iter().product::<usize>().max(1);
        let a_chunk = left_size * trailing;
        let b_chunk = right_size * trailing;
        let mut la = Vec::with_capacity(dims[0] * a_chunk);
        let mut rb = Vec::with_capacity(dims[0] * b_chunk);
        for i in 0..dims[0] {
            let row_start = i * (a_chunk + b_chunk);
            la.extend_from_slice(&up[row_start..row_start + a_chunk]);
            rb.extend_from_slice(&up[row_start + a_chunk..row_start + a_chunk + b_chunk]);
        }
        (la, rb)
    };
    let left = DenseArray::new(Shape::new(left_dims), left_data).expect("shape");
    let right = DenseArray::new(Shape::new(right_dims), right_data).expect("shape");
    (left, right)
}

