125	impl DenseArray {
126	    /// Dot product of two rank-1 vectors.
127	    ///
128	    /// Both must be vectors of the same length. Returns a scalar.
129	    pub fn dot(&self, other: &DenseArray) -> Result<DenseArray, ArrayError> {
130	        if self.rank() != 1 || other.rank() != 1 {
131	            return Err(ArrayError::RankMismatch {
132	                expected: 1,
133	                got: if self.rank() != 1 {
134	                    self.rank()
135	                } else {
136	                    other.rank()
137	                },
138	            });
139	        }
140	        if self.elem_count() != other.elem_count() {
141	            return Err(ArrayError::ShapeMismatch {
142	                source: self.elem_count(),
143	                target: other.elem_count(),
144	            });
145	        }
146	        let sum: f64 = self
147	            .data()
148	            .iter()
149	            .zip(other.data().iter())
150	            .map(|(a, b)| a * b)
151	            .sum();
152	        Ok(DenseArray::from_scalar(sum))
153	    }
154	}
