96	/// Scatter `[B, N, P*P*C]` gradient back to `[B, C, H, W]`
97	/// image space. Each output element of patchify corresponds
98	/// to exactly one input element, so the backward is just the
99	/// inverse indexing -- no accumulation across positions.
100	fn patchify_backward(upstream: &DenseArray, orig_shape: &Shape, p: usize) -> DenseArray {
101	    let dims = orig_shape.dims();
102	    let (b, c, h, w) = (dims[0], dims[1], dims[2], dims[3]);
103	    let nh = h / p;
104	    let nw = w / p;
105	    let n_patches = nh * nw;
106	    let patch_len = p * p * c;
107	    let up = upstream.data();
108	    let mut out = vec![0.0; b * c * h * w];
109	    for b_i in 0..b {
110	        for i in 0..nh {
111	            for j in 0..nw {
112	                let n = i * nw + j;
113	                for c_i in 0..c {
114	                    for dy in 0..p {
115	                        for dx in 0..p {
116	                            let src_y = i * p + dy;
117	                            let src_x = j * p + dx;
118	                            let dst_idx = ((b_i * c + c_i) * h + src_y) * w + src_x;
119	                            let src_idx =
120	                                (b_i * n_patches + n) * patch_len + c_i * p * p + dy * p + dx;
121	                            out[dst_idx] = up[src_idx];
122	                        }
123	                    }
124	                }
125	            }
126	        }
127	    }
128	    DenseArray::new(orig_shape.clone(), out).expect("shape")
129	}
