131	/// Split a concat upstream gradient at `left_size` along
132	/// `axis`. Supports axis 0 (whole-array slice) and axis 1
133	/// (per-row interleaved slice).
134	fn concat_backward(
135	    upstream: &DenseArray,
136	    axis: usize,
137	    left_size: usize,
138	) -> (DenseArray, DenseArray) {
139	    let dims = upstream.shape().dims();
140	    let total = dims[axis];
141	    let right_size = total - left_size;
142	    let mut left_dims = dims.to_vec();
143	    left_dims[axis] = left_size;
144	    let mut right_dims = dims.to_vec();
145	    right_dims[axis] = right_size;
146	    let up = upstream.data();
147	    let (left_data, right_data) = if axis == 0 {
148	        let per_a: usize = dims[1..].iter().product::<usize>().max(1) * left_size;
149	        let per_b: usize = dims[1..].iter().product::<usize>().max(1) * right_size;
150	        (up[..per_a].to_vec(), up[per_a..per_a + per_b].to_vec())
151	    } else {
152	        let trailing: usize = dims[2..].iter().product::<usize>().max(1);
153	        let a_chunk = left_size * trailing;
154	        let b_chunk = right_size * trailing;
155	        let mut la = Vec::with_capacity(dims[0] * a_chunk);
156	        let mut rb = Vec::with_capacity(dims[0] * b_chunk);
157	        for i in 0..dims[0] {
158	            let row_start = i * (a_chunk + b_chunk);
159	            la.extend_from_slice(&up[row_start..row_start + a_chunk]);
160	            rb.extend_from_slice(&up[row_start + a_chunk..row_start + a_chunk + b_chunk]);
161	        }
162	        (la, rb)
163	    };
164	    let left = DenseArray::new(Shape::new(left_dims), left_data).expect("shape");
165	    let right = DenseArray::new(Shape::new(right_dims), right_data).expect("shape");
166	    (left, right)
167	}
