//! Reduction, shape, and matmul methods on [`Tensor`].

use std::rc::Rc;

use mlpl_array::{DenseArray, Shape};

use crate::ops::softmax_forward;
use crate::tape::{NodeData, NodeKind};
use crate::tensor::Tensor;

fn new_tensor(t: &Tensor, value: DenseArray, kind: NodeKind) -> Tensor {
    let node = t.tape.push(NodeData {
        value,
        grad: None,
        kind,
        requires_grad: false,
    });
    Tensor {
        node,
        tape: Rc::clone(&t.tape),
    }
}

impl Tensor {
    /// Sum all elements into a scalar.
    #[must_use]
    pub fn sum(&self) -> Self {
        let s: f64 = self.value().data().iter().sum();
        new_tensor(
            self,
            DenseArray::from_scalar(s),
            NodeKind::SumAll { parent: self.node },
        )
    }

    /// Mean over all elements.
    #[must_use]
    pub fn mean(&self) -> Self {
        let v = self.value();
        let n = v.data().len() as f64;
        let s: f64 = v.data().iter().sum();
        new_tensor(
            self,
            DenseArray::from_scalar(s / n),
            NodeKind::MeanAll { parent: self.node },
        )
    }

    /// Softmax along the last axis (rank-1 or rank-2 inputs).
    #[must_use]
    pub fn softmax(&self) -> Self {
        let v = self.value();
        let axis = v.shape().rank().saturating_sub(1);
        let y = softmax_forward(&v, axis);
        new_tensor(
            self,
            y,
            NodeKind::Softmax {
                parent: self.node,
                axis,
            },
        )
    }

    /// Transpose: reverse axes.
    #[must_use]
    pub fn transpose(&self) -> Self {
        let v = self.value().transpose();
        new_tensor(self, v, NodeKind::Transpose { parent: self.node })
    }

    /// Reshape to `new_shape` (must preserve element count).
    #[must_use]
    pub fn reshape(&self, new_shape: Shape) -> Self {
        let v_orig = self.value();
        let orig_shape = v_orig.shape().clone();
        let v = v_orig.reshape(new_shape).expect("compatible reshape");
        new_tensor(
            self,
            v,
            NodeKind::Reshape {
                parent: self.node,
                orig_shape,
            },
        )
    }

    /// Matrix multiplication `self @ other`.
    #[must_use]
    pub fn matmul(&self, other: &Self) -> Self {
        let v = self
            .value()
            .matmul(&other.value())
            .expect("compatible matmul shapes");
        new_tensor(
            self,
            v,
            NodeKind::MatMul {
                left: self.node,
                right: other.node,
            },
        )
    }

    /// Saga 29 step 005: ViT patch embedding.
    /// `self` must be rank-4 `[B, C, H, W]` and `p` must
    /// divide both `H` and `W`. Returns `[B, N, P*P*C]`.
    #[must_use]
    pub fn patchify(&self, p: usize) -> Self {
        let v_orig = self.value();
        let orig_shape = v_orig.shape().clone();
        let v = v_orig.patchify(p).expect("patchify compatible shape");
        new_tensor(
            self,
            v,
            NodeKind::Patchify {
                parent: self.node,
                orig_shape,
                patch_size: p,
            },
        )
    }

    /// Saga 29 step 005: concat `self` with `other` along
    /// `axis` (0 or 1 supported in this initial release).
    #[must_use]
    pub fn concat(&self, other: &Self, axis: usize) -> Self {
        let a = self.value();
        let b = other.value();
        let left_size = a.shape().dims()[axis];
        let v = a.concat(&b, axis).expect("concat compatible shapes");
        new_tensor(
            self,
            v,
            NodeKind::Concat {
                left: self.node,
                right: other.node,
                axis,
                left_size,
            },
        )
    }
}

//! Built-in function implementations.

use mlpl_array::{DenseArray, Shape};

use crate::error::RuntimeError;
use crate::math_builtins;

/// Names dispatched by the `match` block at the bottom of
/// `call_builtin`. Excludes names handled by the per-module
/// `try_call` chain above (those are listed in each module's
/// own `NAMES` constant).
pub(crate) const LOCAL_NAMES: &[&str] = &[
    "iota",
    "shape",
    "rank",
    "reshape",
    "transpose",
    "reduce_add",
    "reduce_mul",
    "argmax",
    "dot",
    "matmul",
    "grid",
    "patchify",
    // Note: `concat` is not listed here. The 3-arg
    // axis-aware form (Saga 29 step 005) is dispatched
    // below alongside the 2-arg legacy form registered in
    // `math_builtins::NAMES`. Both arities flow through this
    // file's `call_builtin` -> 3-arg falls through
    // `math_builtins::try_call` and hits the `"concat"` arm
    // in the match below.
];

macro_rules! check_arity {
    ($name:expr, $expected:expr, $args:expr) => {
        if $args.len() != $expected {
            return Err(RuntimeError::ArityMismatch {
                func: $name.into(),
                expected: $expected,
                got: $args.len(),
            });
        }
    };
}

/// Dispatch a built-in function call by name.
pub fn call_builtin(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    // Try math/constructor builtins first
    if let Some(result) = math_builtins::try_call(name, args.clone()) {
        return result;
    }
    if let Some(result) = crate::random_builtins::try_call(name, args.clone()) {
        return result;
    }
    if let Some(result) = crate::dataset_builtins::try_call(name, args.clone()) {
        return result;
    }
    if let Some(result) = crate::ml_builtins::try_call(name, args.clone()) {
        return result;
    }
    if let Some(result) = crate::ensemble_builtins::try_call(name, args.clone()) {
        return result;
    }
    if let Some(result) = crate::embedding_builtins::try_call(name, args.clone()) {
        return result;
    }
    if let Some(result) = crate::tsne_builtin::try_call(name, args.clone()) {
        return result;
    }
    if let Some(result) = crate::pca_builtin::try_call(name, args.clone()) {
        return result;
    }
    match name {
        "iota" => builtin_iota(name, args),
        "shape" => builtin_shape(name, args),
        "rank" => builtin_rank(name, args),
        "reshape" => builtin_reshape(name, args),
        "transpose" => builtin_transpose(name, args),
        "reduce_add" | "reduce_mul" => builtin_reduce(name, args),
        "argmax" => builtin_argmax(name, args),
        "dot" => {
            check_arity!(name, 2, args);
            Ok(args[0].dot(&args[1])?)
        }
        "matmul" => {
            check_arity!(name, 2, args);
            Ok(args[0].matmul(&args[1])?)
        }
        "grid" => crate::grid_builtin::builtin_grid(name, args),
        "patchify" => builtin_patchify(name, args),
        "concat" => builtin_concat(name, args),
        _ => Err(RuntimeError::UnknownFunction(name.into())),
    }
}

fn builtin_iota(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    check_arity!(name, 1, args);
    if args[0].rank() != 0 {
        return Err(RuntimeError::InvalidArgument {
            func: name.into(),
            reason: format!("expected scalar, got rank {}", args[0].rank()),
        });
    }
    let n = args[0].data()[0] as usize;
    let data: Vec<f64> = (0..n).map(|i| i as f64).collect();
    Ok(DenseArray::from_vec(data))
}

fn builtin_shape(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    check_arity!(name, 1, args);
    let dims: Vec<f64> = args[0].shape().dims().iter().map(|&d| d as f64).collect();
    Ok(DenseArray::from_vec(dims))
}

fn builtin_rank(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    check_arity!(name, 1, args);
    Ok(DenseArray::from_scalar(args[0].rank() as f64))
}

fn builtin_reshape(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    check_arity!(name, 2, args);
    let shape_data = args[1].data();
    let dims: Vec<usize> = shape_data.iter().map(|&d| d as usize).collect();
    Ok(args[0].reshape(Shape::new(dims))?)
}

fn builtin_transpose(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    check_arity!(name, 1, args);
    Ok(args[0].transpose())
}

fn builtin_argmax(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    if args.len() == 1 {
        // Flat argmax over all elements, returned as a scalar index.
        let data = args[0].data();
        if data.is_empty() {
            return Err(RuntimeError::InvalidArgument {
                func: name.into(),
                reason: "argmax of empty array".into(),
            });
        }
        let mut best_idx = 0usize;
        let mut best_val = data[0];
        for (i, &v) in data.iter().enumerate().skip(1) {
            if v > best_val {
                best_val = v;
                best_idx = i;
            }
        }
        return Ok(DenseArray::from_scalar(best_idx as f64));
    }
    if args.len() != 2 {
        return Err(RuntimeError::ArityMismatch {
            func: name.into(),
            expected: 2,
            got: args.len(),
        });
    }
    if args[1].rank() != 0 {
        return Err(RuntimeError::InvalidArgument {
            func: name.into(),
            reason: format!("axis must be scalar, got rank {}", args[1].rank()),
        });
    }
    let axis = args[1].data()[0] as usize;
    Ok(args[0].argmax_axis(axis)?)
}

fn builtin_reduce(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    if args.len() != 1 && args.len() != 2 {
        return Err(RuntimeError::ArityMismatch {
            func: name.into(),
            expected: 1,
            got: args.len(),
        });
    }
    let (identity, op): (f64, fn(f64, f64) -> f64) = match name {
        "reduce_add" => (0.0, |a, b| a + b),
        "reduce_mul" => (1.0, |a, b| a * b),
        _ => unreachable!(),
    };
    if args.len() == 2 {
        if args[1].rank() != 0 {
            return Err(RuntimeError::InvalidArgument {
                func: name.into(),
                reason: format!("axis must be scalar, got rank {}", args[1].rank()),
            });
        }
        let axis = args[1].data()[0] as usize;
        Ok(args[0].reduce_axis(axis, identity, op)?)
    } else {
        let result = args[0].data().iter().copied().fold(identity, op);
        Ok(DenseArray::from_scalar(result))
    }
}

fn builtin_patchify(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    check_arity!(name, 2, args);
    let p = scalar_usize(name, &args[1], "patch_size")?;
    Ok(args[0].patchify(p)?)
}

fn builtin_concat(name: &str, args: Vec<DenseArray>) -> Result<DenseArray, RuntimeError> {
    check_arity!(name, 3, args);
    let axis = scalar_usize(name, &args[2], "axis")?;
    Ok(args[0].concat(&args[1], axis)?)
}

fn scalar_usize(name: &str, arr: &DenseArray, what: &str) -> Result<usize, RuntimeError> {
    if arr.rank() != 0 {
        return Err(RuntimeError::InvalidArgument {
            func: name.into(),
            reason: format!("{what} must be a scalar, got rank {}", arr.rank()),
        });
    }
    let v = arr.data()[0];
    if v < 0.0 || v.fract() != 0.0 {
        return Err(RuntimeError::InvalidArgument {
            func: name.into(),
            reason: format!("{what} must be a non-negative integer, got {v}"),
        });
    }
    Ok(v as usize)
}

