252	/// tape helper stays inside the 7-arg clippy budget without needing
253	/// `#[allow(clippy::too_many_arguments)]`.
254	struct AttentionInputs<'a> {
255	    wq: &'a str,
256	    wk: &'a str,
257	    wv: &'a str,
258	    wo: &'a str,
259	    d_model: usize,
260	    causal: bool,
261	}
262	
263	/// Single-head scaled-dot-product attention on the tape. Multi-head
264	/// requires slicing that the autograd substrate does not yet expose.
265	fn attention_single_head_tape(
266	    x: &Tensor,
267	    inputs: &AttentionInputs<'_>,
268	    tape: &Rc<Tape>,
269	    params: &HashMap<String, Tensor>,
270	) -> Result<Tensor, EvalError> {
271	    let dims = x.value().shape().dims().to_vec();
272	    if dims.len() != 2 || dims[1] != inputs.d_model {
273	        return Err(EvalError::Unsupported(format!(
274	            "attention: input must be [seq, {}], got {dims:?}",
275	            inputs.d_model
276	        )));
277	    }
278	    let fetch = |name: &str| -> Result<Tensor, EvalError> {
279	        params
280	            .get(name)
281	            .cloned()
282	            .ok_or_else(|| EvalError::UndefinedVariable(name.into()))
283	    };
284	    let wq_t = fetch(inputs.wq)?;
285	    let wk_t = fetch(inputs.wk)?;
286	    let wv_t = fetch(inputs.wv)?;
287	    let wo_t = fetch(inputs.wo)?;
288	    let q = x.matmul(&wq_t);
289	    let k = x.matmul(&wk_t);
290	    let v = x.matmul(&wv_t);
291	    let scale = Tensor::leaf(
292	        Rc::clone(tape),
293	        DenseArray::from_scalar(1.0 / (inputs.d_model as f64).sqrt()),
294	        false,
