6	impl fmt::Display for DenseArray {
7	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
8	        if self.elem_count() == 0 {
9	            return write!(f, "[]");
10	        }
11	        match self.rank() {
12	            0 => write!(f, "{}", self.data()[0]),
13	            1 => write_row(f, self.data()),
14	            2 => {
15	                let cols = self.shape().dims()[1];
16	                for (i, row) in self.data().chunks(cols).enumerate() {
17	                    if i > 0 {
18	                        writeln!(f)?;
19	                    }
20	                    write_row(f, row)?;
21	                }
22	                Ok(())
23	            }
24	            _ => write!(f, "{:?}", self.data()),
25	        }
26	    }
27	}
