1	//! Gallery rendering: turn an `[N, 3, H, W]` image batch
2	//! into an SVG grid of thumbnails. Saga 29 step 010.
3	//!
4	//! Each batch entry is treated as a single RGB image with
5	//! channel-first layout (`[3, H, W]` -- the same layout the
6	//! `load_preloaded("pets_tiny")` fixture and `load_images`
7	//! builtin produce). Values are expected in `[-1, 1]`
8	//! (the normalized space) but values outside that range are
9	//! clamped at render time so a stray un-normalized tensor
10	//! still renders, just with all the colors saturated.
11	//!
12	//! The thumbnails are downsampled to fit the gallery cell
13	//! size via block averaging -- so a `[20, 3, 64, 64]`
14	//! pets_tiny slice renders as twenty ~40x40 thumbnails in
15	//! the 400x300 SVG canvas without emitting 80K `<rect>`
16	//! elements.
17	
18	use mlpl_array::DenseArray;
19	
20	use super::{H, PAD, VizError, W, write_svg_close, write_svg_open};
21	
22	/// Maximum displayed thumbnail size (in SVG units). The grid
23	/// scales thumbnails DOWN to fit the canvas; thumbnails are
24	/// not stretched UP beyond their source resolution.
25	const MAX_THUMB: f64 = 60.0;
26	
27	/// Render an `[N, 3, H, W]` batch as a grid of RGB
28	/// thumbnails. Returns a self-contained SVG string.
29	pub fn render_gallery(data: &DenseArray) -> Result<String, VizError> {
30	    let dims = data.shape().dims();
31	    if dims.len() != 4 || dims[1] != 3 {
32	        return Err(VizError::InvalidShape(format!(
33	            "gallery expects [N, 3, H, W] shape, got {dims:?}"
34	        )));
35	    }
36	    let n = dims[0];
37	    let src_h = dims[2];
38	    let src_w = dims[3];
39	    let mut out = String::new();
40	    write_svg_open(&mut out);
41	    if n == 0 || src_h == 0 || src_w == 0 {
42	        write_svg_close(&mut out);
43	        return Ok(out);
44	    }
45	    let cols = (n as f64).sqrt().ceil() as usize;
46	    let rows = n.div_ceil(cols);
47	    let cell_w = (W - 2.0 * PAD) / cols as f64;
48	    let cell_h = (H - 2.0 * PAD) / rows as f64;
49	    let thumb_size = cell_w.min(cell_h).min(MAX_THUMB);
50	    let (thumb_h_px, thumb_w_px) = (
51	        src_h.min(thumb_size as usize),
52	        src_w.min(thumb_size as usize),
53	    );
54	    let raw = data.data();
55	    let stride_n = 3 * src_h * src_w;
56	    for idx in 0..n {
57	        let col = idx % cols;
58	        let row = idx / cols;
59	        let cell_x = PAD + cell_w * col as f64 + (cell_w - thumb_size) * 0.5;
60	        let cell_y = PAD + cell_h * row as f64 + (cell_h - thumb_size) * 0.5;
61	        let img = &raw[idx * stride_n..(idx + 1) * stride_n];
62	        render_thumbnail(
63	            &mut out, img, src_h, src_w, thumb_h_px, thumb_w_px, cell_x, cell_y, thumb_size,
64	        );
65	    }
66	    write_svg_close(&mut out);
67	    Ok(out)
68	}
69	
70	#[allow(clippy::too_many_arguments)]
71	fn render_thumbnail(
72	    out: &mut String,
73	    img: &[f64],
74	    src_h: usize,
75	    src_w: usize,
76	    thumb_h_px: usize,
77	    thumb_w_px: usize,
78	    cell_x: f64,
79	    cell_y: f64,
80	    thumb_size: f64,
81	) {
82	    let pixel_w = thumb_size / thumb_w_px as f64;
83	    let pixel_h = thumb_size / thumb_h_px as f64;
84	    let block_h = src_h as f64 / thumb_h_px as f64;
85	    let block_w = src_w as f64 / thumb_w_px as f64;
86	    let chan_stride = src_h * src_w;
87	    for ty in 0..thumb_h_px {
88	        for tx in 0..thumb_w_px {
89	            let y0 = (ty as f64 * block_h) as usize;
90	            let y1 = (((ty as f64 + 1.0) * block_h) as usize)
91	                .max(y0 + 1)
92	                .min(src_h);
93	            let x0 = (tx as f64 * block_w) as usize;
94	            let x1 = (((tx as f64 + 1.0) * block_w) as usize)
95	                .max(x0 + 1)
96	                .min(src_w);
97	            let mut sum = [0.0_f64; 3];
98	            let mut count = 0.0_f64;
99	            for c in 0..3 {
100	                for sy in y0..y1 {
101	                    for sx in x0..x1 {
102	                        sum[c] += img[c * chan_stride + sy * src_w + sx];
103	                    }
104	                }
105	            }
106	            count += ((y1 - y0) * (x1 - x0)) as f64;
107	            let inv = if count > 0.0 { 1.0 / count } else { 1.0 };
108	            let r = norm_to_u8(sum[0] * inv);
109	            let g = norm_to_u8(sum[1] * inv);
110	            let b = norm_to_u8(sum[2] * inv);
111	            let px = cell_x + tx as f64 * pixel_w;
112	            let py = cell_y + ty as f64 * pixel_h;
113	            out.push_str(&format!(
114	                "<rect x=\"{px:.1}\" y=\"{py:.1}\" width=\"{pixel_w:.2}\" height=\"{pixel_h:.2}\" fill=\"rgb({r},{g},{b})\"/>"
115	            ));
116	        }
117	    }
118	}
119	
120	/// Map a `[-1, 1]`-normalized pixel value to a `[0, 255]`
121	/// u8 channel. Values outside the range clamp instead of
122	/// wrapping so non-pets_tiny data still renders.
123	fn norm_to_u8(v: f64) -> u8 {
124	    let unit = ((v + 1.0) * 127.5).clamp(0.0, 255.0);
125	    unit.round() as u8
126	}

