//! Gallery rendering: turn an `[N, 3, H, W]` image batch
//! into an SVG grid of thumbnails. Saga 29 step 010.
//!
//! Each batch entry is treated as a single RGB image with
//! channel-first layout (`[3, H, W]` -- the same layout the
//! `load_preloaded("pets_tiny")` fixture and `load_images`
//! builtin produce). Values are expected in `[-1, 1]`
//! (the normalized space) but values outside that range are
//! clamped at render time so a stray un-normalized tensor
//! still renders, just with all the colors saturated.
//!
//! The thumbnails are downsampled to fit the gallery cell
//! size via block averaging -- so a `[20, 3, 64, 64]`
//! pets_tiny slice renders as twenty ~40x40 thumbnails in
//! the 400x300 SVG canvas without emitting 80K `<rect>`
//! elements.

use mlpl_array::DenseArray;

use super::{H, PAD, VizError, W, write_svg_close, write_svg_open};

/// Maximum displayed thumbnail size (in SVG units). The grid
/// scales thumbnails DOWN to fit the canvas; thumbnails are
/// not stretched UP beyond their source resolution.
const MAX_THUMB: f64 = 60.0;

/// Render an `[N, 3, H, W]` batch as a grid of RGB
/// thumbnails. Returns a self-contained SVG string.
pub fn render_gallery(data: &DenseArray) -> Result<String, VizError> {
    let dims = data.shape().dims();
    if dims.len() != 4 || dims[1] != 3 {
        return Err(VizError::InvalidShape(format!(
            "gallery expects [N, 3, H, W] shape, got {dims:?}"
        )));
    }
    let n = dims[0];
    let src_h = dims[2];
    let src_w = dims[3];
    let mut out = String::new();
    write_svg_open(&mut out);
    if n == 0 || src_h == 0 || src_w == 0 {
        write_svg_close(&mut out);
        return Ok(out);
    }
    let cols = (n as f64).sqrt().ceil() as usize;
    let rows = n.div_ceil(cols);
    let cell_w = (W - 2.0 * PAD) / cols as f64;
    let cell_h = (H - 2.0 * PAD) / rows as f64;
    let thumb_size = cell_w.min(cell_h).min(MAX_THUMB);
    let (thumb_h_px, thumb_w_px) = (
        src_h.min(thumb_size as usize),
        src_w.min(thumb_size as usize),
    );
    let raw = data.data();
    let stride_n = 3 * src_h * src_w;
    for idx in 0..n {
        let col = idx % cols;
        let row = idx / cols;
        let cell_x = PAD + cell_w * col as f64 + (cell_w - thumb_size) * 0.5;
        let cell_y = PAD + cell_h * row as f64 + (cell_h - thumb_size) * 0.5;
        let img = &raw[idx * stride_n..(idx + 1) * stride_n];
        render_thumbnail(
            &mut out, img, src_h, src_w, thumb_h_px, thumb_w_px, cell_x, cell_y, thumb_size,
        );
    }
    write_svg_close(&mut out);
    Ok(out)
}

#[allow(clippy::too_many_arguments)]
fn render_thumbnail(
    out: &mut String,
    img: &[f64],
    src_h: usize,
    src_w: usize,
    thumb_h_px: usize,
    thumb_w_px: usize,
    cell_x: f64,
    cell_y: f64,
    thumb_size: f64,
) {
    let pixel_w = thumb_size / thumb_w_px as f64;
    let pixel_h = thumb_size / thumb_h_px as f64;
    let block_h = src_h as f64 / thumb_h_px as f64;
    let block_w = src_w as f64 / thumb_w_px as f64;
    let chan_stride = src_h * src_w;
    for ty in 0..thumb_h_px {
        for tx in 0..thumb_w_px {
            let y0 = (ty as f64 * block_h) as usize;
            let y1 = (((ty as f64 + 1.0) * block_h) as usize)
                .max(y0 + 1)
                .min(src_h);
            let x0 = (tx as f64 * block_w) as usize;
            let x1 = (((tx as f64 + 1.0) * block_w) as usize)
                .max(x0 + 1)
                .min(src_w);
            let mut sum = [0.0_f64; 3];
            let mut count = 0.0_f64;
            for c in 0..3 {
                for sy in y0..y1 {
                    for sx in x0..x1 {
                        sum[c] += img[c * chan_stride + sy * src_w + sx];
                    }
                }
            }
            count += ((y1 - y0) * (x1 - x0)) as f64;
            let inv = if count > 0.0 { 1.0 / count } else { 1.0 };
            let r = norm_to_u8(sum[0] * inv);
            let g = norm_to_u8(sum[1] * inv);
            let b = norm_to_u8(sum[2] * inv);
            let px = cell_x + tx as f64 * pixel_w;
            let py = cell_y + ty as f64 * pixel_h;
            out.push_str(&format!(
                "<rect x=\"{px:.1}\" y=\"{py:.1}\" width=\"{pixel_w:.2}\" height=\"{pixel_h:.2}\" fill=\"rgb({r},{g},{b})\"/>"
            ));
        }
    }
}

/// Map a `[-1, 1]`-normalized pixel value to a `[0, 255]`
/// u8 channel. Values outside the range clamp instead of
/// wrapping so non-pets_tiny data still renders.
fn norm_to_u8(v: f64) -> u8 {
    let unit = ((v + 1.0) * 127.5).clamp(0.0, 255.0);
    unit.round() as u8
}

//! SVG diagram rendering for MLPL arrays.

mod charts;
mod decision_boundary;
mod gallery;
mod heatmap;
mod scatter;

use std::fmt;

use mlpl_array::DenseArray;

pub use charts::{render_bar, render_line};
pub use decision_boundary::render_decision_boundary;
pub use gallery::render_gallery;
pub use heatmap::render_heatmap;
pub use scatter::{render_scatter, render_scatter3d};

pub(crate) const W: f64 = 400.0;
pub(crate) const H: f64 = 300.0;
pub(crate) const PAD: f64 = 30.0;

/// Plain min/max of a slice (no expansion when all equal).
pub(crate) fn data_range(values: &[f64]) -> (f64, f64) {
    let mut lo = f64::INFINITY;
    let mut hi = f64::NEG_INFINITY;
    for &v in values {
        if v < lo {
            lo = v;
        }
        if v > hi {
            hi = v;
        }
    }
    (lo, hi)
}

/// Min/max of a slice, returning (lo-1, hi+1) when all values are equal
/// so the resulting range is non-zero.
pub(crate) fn bounds(values: &[f64]) -> (f64, f64) {
    let mut lo = f64::INFINITY;
    let mut hi = f64::NEG_INFINITY;
    for &v in values {
        if v < lo {
            lo = v;
        }
        if v > hi {
            hi = v;
        }
    }
    if lo == hi {
        (lo - 1.0, hi + 1.0)
    } else {
        (lo, hi)
    }
}

/// Scale a data coordinate to plot pixels. `axis` 0 = x, 1 = y (flipped).
pub(crate) fn scale(v: f64, lo: f64, hi: f64, axis: u8) -> f64 {
    let t = (v - lo) / (hi - lo);
    if axis == 0 {
        PAD + t * (W - 2.0 * PAD)
    } else {
        H - PAD - t * (H - 2.0 * PAD)
    }
}

pub(crate) fn write_svg_open(out: &mut String) {
    out.push_str(&format!(
        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 {W} {H}\" width=\"{W}\" height=\"{H}\">"
    ));
    out.push_str("<rect width=\"100%\" height=\"100%\" fill=\"#1e1e2e\"/>");
    let (x0, x1, y0, y1) = (PAD, W - PAD, PAD, H - PAD);
    out.push_str(&format!(
        "<line x1=\"{x0}\" y1=\"{y1}\" x2=\"{x1}\" y2=\"{y1}\" stroke=\"#45475a\" stroke-width=\"1\"/>"
    ));
    out.push_str(&format!(
        "<line x1=\"{x0}\" y1=\"{y0}\" x2=\"{x0}\" y2=\"{y1}\" stroke=\"#45475a\" stroke-width=\"1\"/>"
    ));
}

pub(crate) fn write_svg_close(out: &mut String) {
    out.push_str("</svg>");
}

/// Errors produced by SVG rendering.
#[derive(Clone, Debug, PartialEq)]
pub enum VizError {
    /// The data shape is not valid for the requested diagram.
    InvalidShape(String),
    /// The diagram type name is not recognized.
    UnknownType(String),
}

impl fmt::Display for VizError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidShape(s) => write!(f, "invalid shape for diagram: {s}"),
            Self::UnknownType(s) => write!(f, "unknown svg type: '{s}'"),
        }
    }
}

impl std::error::Error for VizError {}

/// Dispatch on a diagram type name. Returns the rendered SVG string.
pub fn render(data: &DenseArray, type_name: &str) -> Result<String, VizError> {
    render_with_aux(data, type_name, None)
}

/// Dispatch on a diagram type name with an optional auxiliary array.
/// Diagrams that need extra inputs (e.g. `decision_boundary` needs the
/// training points) read them from `aux`.
pub fn render_with_aux(
    data: &DenseArray,
    type_name: &str,
    aux: Option<&DenseArray>,
) -> Result<String, VizError> {
    match type_name {
        "scatter" => render_scatter(data),
        "scatter3d" => render_scatter3d(data),
        "line" => render_line(data),
        "bar" => render_bar(data),
        "heatmap" => render_heatmap(data),
        "gallery" => render_gallery(data),
        "decision_boundary" => {
            let training = aux.ok_or_else(|| {
                VizError::InvalidShape(
                    "decision_boundary requires a third argument (training points Nx3)".into(),
                )
            })?;
            render_decision_boundary(data, training)
        }
        other => Err(VizError::UnknownType(other.to_string())),
    }
}

//! `render_gallery` tests. Saga 29 step 010.

use mlpl_array::{DenseArray, Shape};
use mlpl_viz::{VizError, render, render_gallery};

fn arr(dims: Vec<usize>, data: Vec<f64>) -> DenseArray {
    DenseArray::new(Shape::new(dims), data).unwrap()
}

#[test]
fn gallery_rejects_non_rank4_input() {
    let x = arr(vec![3, 64, 64], vec![0.0; 3 * 64 * 64]);
    let err = render_gallery(&x).unwrap_err();
    assert!(matches!(err, VizError::InvalidShape(_)));
}

#[test]
fn gallery_rejects_wrong_channel_count() {
    let x = arr(vec![2, 4, 8, 8], vec![0.0; 2 * 4 * 8 * 8]);
    let err = render_gallery(&x).unwrap_err();
    assert!(matches!(err, VizError::InvalidShape(_)));
}

#[test]
fn gallery_renders_single_image() {
    // 1x3x4x4 rainbow-ish gradient: each channel ramps.
    let mut data: Vec<f64> = Vec::with_capacity(3 * 4 * 4);
    for c in 0..3 {
        for y in 0..4 {
            for x in 0..4 {
                let v = match c {
                    0 => (x as f64) / 3.0,
                    1 => (y as f64) / 3.0,
                    _ => ((x + y) as f64) / 6.0,
                };
                data.push(v * 2.0 - 1.0); // [0, 1] -> [-1, 1]
            }
        }
    }
    let x = arr(vec![1, 3, 4, 4], data);
    let svg = render_gallery(&x).expect("render gallery");
    assert!(svg.starts_with("<svg"));
    assert!(svg.ends_with("</svg>"));
    // At least one fill="rgb(...)" rect was emitted per pixel.
    let rect_count = svg.matches("<rect").count();
    assert!(
        rect_count > 16,
        "expected at least 16 pixel rects, got {rect_count}"
    );
}

#[test]
fn gallery_layout_uses_grid_for_multi_image_batch() {
    // 4 images -> 2x2 grid expected.
    let n = 4;
    let h = 4;
    let w = 4;
    let mut data: Vec<f64> = Vec::with_capacity(n * 3 * h * w);
    for i in 0..n {
        for c in 0..3 {
            for _ in 0..(h * w) {
                // Distinct intensity per image / channel so the
                // SVG output reflects all four.
                data.push((i as f64 + c as f64 * 0.1) / 6.0 * 2.0 - 1.0);
            }
        }
    }
    let x = arr(vec![n, 3, h, w], data);
    let svg = render_gallery(&x).expect("render gallery");
    // For a 2x2 thumbnail grid each image's top-left corner
    // should land at a distinct (x, y). We don't try to
    // pin exact pixel positions (those depend on padding /
    // canvas math); just check we got enough rects.
    let rect_count = svg.matches("<rect").count();
    assert!(
        rect_count >= n * 4,
        "expected >= {} rects across the grid, got {}",
        n * 4,
        rect_count
    );
}

#[test]
fn gallery_handles_empty_batch() {
    let x = arr(vec![0, 3, 4, 4], vec![]);
    let svg = render_gallery(&x).expect("render gallery on empty batch");
    assert!(svg.starts_with("<svg"));
    assert!(svg.ends_with("</svg>"));
}

#[test]
fn gallery_clamps_out_of_range_pixels_without_panicking() {
    // Values way outside [-1, 1] should clamp, not panic.
    let n = 1;
    let h = 4;
    let w = 4;
    let data: Vec<f64> = (0..(3 * h * w))
        .map(|i| if i % 2 == 0 { -1e6 } else { 1e6 })
        .collect();
    let x = arr(vec![n, 3, h, w], data);
    let svg = render_gallery(&x).expect("render gallery on extreme values");
    assert!(svg.contains("<rect"));
    // Saturated colors: rgb(0, ...) or rgb(255, ...) should be
    // present somewhere.
    assert!(
        svg.contains("rgb(0,0,0)")
            || svg.contains("rgb(255,255,255)")
            || svg.contains("rgb(255,0,255)")
    );
}

#[test]
fn dispatch_via_render_gallery_string() {
    // The svg() builtin dispatch routes "gallery" type to
    // render_gallery via the shared render(...) entry.
    let n = 2;
    let data: Vec<f64> = (0..(n * 3 * 4 * 4))
        .map(|i| (i as f64) / 100.0 - 1.0)
        .collect();
    let x = arr(vec![n, 3, 4, 4], data);
    let svg = render(&x, "gallery").expect("dispatch through render(...)");
    assert!(svg.starts_with("<svg"));
}

