/// Saga 29 step 012: shared dispatcher for the Result
/// accessors. Each variant eval-borrows the argument, then
/// pattern-matches on `Value::Result` to return the
/// appropriate inner value or error. Kept as one function
/// to stay under the module-function-count budget; the
/// per-accessor surface is small enough to share a body.
fn eval_result_accessor(
    name: &str,
    args: &[Expr],
    env: &mut Environment,
    trace: &mut Option<&mut Trace>,
) -> Result<Value, EvalError> {
    let want = if name == "unwrap_or" { 2 } else { 1 };
    if args.len() != want {
        return Err(EvalError::BadArity {
            func: name.into(),
            expected: want,
            got: args.len(),
        });
    }
    let recv = eval_expr(&args[0], env, trace)?;
    match (name, recv) {
        ("is_ok", Value::Result { ok, .. }) => {
            Ok(Value::Array(DenseArray::from_scalar(if ok { 1.0 } else { 0.0 })))
        }
        ("is_err", Value::Result { ok, .. }) => {
            Ok(Value::Array(DenseArray::from_scalar(if ok { 0.0 } else { 1.0 })))
        }
        ("unwrap", Value::Result { ok, payload }) => {
            if ok {
                Ok(*payload)
            } else {
                Err(EvalError::UnwrapOnErr {
                    message: format!("{payload}"),
                })
            }
        }
        ("err_message", Value::Result { ok, payload }) => {
            if !ok {
                Ok(*payload)
            } else {
                Err(EvalError::Unsupported(format!(
                    "err_message: receiver is Ok({payload}), not Err(_)"
                )))
            }
        }
        ("unwrap_or", Value::Result { ok, payload }) => {
            if ok {
                Ok(*payload)
            } else {
                eval_expr(&args[1], env, trace)
            }
        }
        (accessor, other) => Err(EvalError::NotAResult {
            receiver_kind: value_kind(&other),
            accessor: match accessor {
                "is_ok" => "is_ok",
                "is_err" => "is_err",
                "unwrap" => "unwrap",
                "err_message" => "err_message",
                "unwrap_or" => "unwrap_or",
                _ => "result-accessor",
            },
        }),
    }
}
