//! HTTP route handlers. Saga R1 step 002.
//!
//! `/v1/eval-on-device` runs program blocks against
//! a fresh Environment populated with caller-
//! supplied bindings; the result tensor (or string)
//! is stashed on the peer's handle store and
//! returned as an opaque handle. `/transfer` pulls
//! the bytes back. `/release-handle` cleans up.

use axum::Json;
use axum::extract::{Path, State};
use axum::http::{HeaderMap, StatusCode};
use axum::response::IntoResponse;
use mlpl_eval::{Environment, Value, eval_program_value};
use mlpl_parser::{lex, parse};
use mlpl_serve::auth::{AuthMode, check_token, extract_bearer};
use mlpl_serve::handlers::{CreateSessionResponse, ErrorResponse};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::server::AppState;

#[derive(Serialize)]
pub struct HealthResponse {
    pub status: &'static str,
    pub version: &'static str,
    pub device: &'static str,
}

#[derive(Deserialize)]
pub struct EvalOnDeviceBinding {
    pub name: String,
    pub tensor: String,
}

#[derive(Deserialize)]
pub struct EvalOnDeviceRequest {
    pub program: String,
    #[serde(default)]
    pub bindings: Vec<EvalOnDeviceBinding>,
}

#[derive(Serialize)]
#[serde(tag = "kind", rename_all = "lowercase")]
pub enum EvalResultPayload {
    Tensor {
        handle: String,
        shape: Vec<usize>,
        device: &'static str,
    },
    String {
        value: String,
    },
}

#[derive(Serialize)]
pub struct EvalOnDeviceResponse {
    pub result: EvalResultPayload,
}

#[derive(Deserialize)]
pub struct TransferRequest {
    pub handle: String,
}

#[derive(Serialize)]
pub struct TransferResponse {
    pub tensor: String,
}

/// `GET /v1/health` -- no auth.
pub async fn health_handler() -> impl IntoResponse {
    Json(HealthResponse {
        status: "ok",
        version: env!("CARGO_PKG_VERSION"),
        device: "mlx",
    })
}

/// `POST /v1/sessions` -- no auth. Delegates to
/// mlpl-serve's session creation. Step 002 keeps
/// the same shape as step 001; pushing
/// `device("mlx")` onto the env's device stack at
/// creation time stays out -- per-eval push in the
/// eval-on-device handler is the simpler path for
/// now.
pub async fn create_session_handler(State(state): State<AppState>) -> impl IntoResponse {
    // Saga 21.5 step 003 added an InterruptMap to mlpl-serve's
    // `create_session` signature for the orchestrator-side
    // `/cancel` endpoint. mlpl-mlx-serve doesn't expose
    // cancellation today, so we hand in a throwaway map; it
    // gets dropped right after construction.
    let throwaway = mlpl_serve::sessions::new_interrupt_map();
    let (id, token) = mlpl_serve::sessions::create_session(&state.sessions, &throwaway).await;
    (
        StatusCode::OK,
        Json(CreateSessionResponse {
            session_id: id,
            token,
        }),
    )
}

/// `POST /v1/sessions/{id}/eval-on-device` -- auth
/// required when `auth_mode == Required`. Decodes
/// each binding, runs the program against a fresh
/// sub-Environment, stashes any tensor result on
/// the handle store, returns either a tensor handle
/// or a string value.
pub async fn eval_on_device_handler(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(body): Json<EvalOnDeviceRequest>,
) -> Result<Json<EvalOnDeviceResponse>, (StatusCode, Json<ErrorResponse>)> {
    auth_for_session(&state, id, &headers).await?;
    let mut sub = Environment::new();
    for binding in &body.bindings {
        let arr = crate::wire::decode_from_json(&binding.tensor).map_err(|e| {
            (
                StatusCode::BAD_REQUEST,
                json_err(format!("binding {:?}: {e}", binding.name)),
            )
        })?;
        sub.set(binding.name.clone(), arr);
    }
    let tokens = lex(&body.program)
        .map_err(|e| (StatusCode::BAD_REQUEST, json_err(format!("lex: {e:?}"))))?;
    let stmts =
        parse(&tokens).map_err(|e| (StatusCode::BAD_REQUEST, json_err(format!("parse: {e:?}"))))?;
    let value = eval_program_value(&stmts, &mut sub)
        .map_err(|e| (StatusCode::BAD_REQUEST, json_err(format!("{e}"))))?;
    let payload = match value {
        Value::Array(a) => {
            let shape = a.shape().dims().to_vec();
            let handle = crate::handles::insert(&state.handles, a).await;
            EvalResultPayload::Tensor {
                handle: handle.to_string(),
                shape,
                device: "mlx",
            }
        }
        Value::Str(s) => EvalResultPayload::String { value: s },
        Value::Model(_)
        | Value::Tokenizer(_)
        | Value::DeviceTensor { .. }
        | Value::BuiltinRef { .. }
        | Value::Record { .. }
        | Value::StrList { .. }
        | Value::Result { .. } => {
            return Err((
                StatusCode::BAD_REQUEST,
                json_err(
                    "eval-on-device blocks must return a tensor or string in R1 \
                     (got model / tokenizer / device-tensor / builtin-ref / record / string-list / result)",
                ),
            ));
        }
    };
    Ok(Json(EvalOnDeviceResponse { result: payload }))
}

/// `POST /v1/sessions/{id}/transfer` -- auth
/// required. Pulls a handle's bytes back via the
/// versioned envelope wire format.
pub async fn transfer_handler(
    State(state): State<AppState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(body): Json<TransferRequest>,
) -> Result<Json<TransferResponse>, (StatusCode, Json<ErrorResponse>)> {
    auth_for_session(&state, id, &headers).await?;
    let handle_uuid = Uuid::parse_str(&body.handle)
        .map_err(|e| (StatusCode::BAD_REQUEST, json_err(format!("handle: {e}"))))?;
    let arr = crate::handles::get(&state.handles, &handle_uuid)
        .await
        .ok_or_else(|| (StatusCode::NOT_FOUND, json_err("unknown handle")))?;
    let tensor = crate::wire::encode_for_json(&arr).map_err(|e| {
        (
            StatusCode::INTERNAL_SERVER_ERROR,
            json_err(format!("encode: {e}")),
        )
    })?;
    Ok(Json(TransferResponse { tensor }))
}

/// `POST /v1/sessions/{id}/release-handle/{handle}`
/// -- auth required. Removes the handle from the
/// store; idempotent (404 if already released).
pub async fn release_handle_handler(
    State(state): State<AppState>,
    Path((id, handle)): Path<(Uuid, String)>,
    headers: HeaderMap,
) -> Result<StatusCode, (StatusCode, Json<ErrorResponse>)> {
    auth_for_session(&state, id, &headers).await?;
    let handle_uuid = Uuid::parse_str(&handle)
        .map_err(|e| (StatusCode::BAD_REQUEST, json_err(format!("handle: {e}"))))?;
    match crate::handles::release(&state.handles, &handle_uuid).await {
        Some(_) => Ok(StatusCode::NO_CONTENT),
        None => Err((StatusCode::NOT_FOUND, json_err("unknown handle"))),
    }
}

async fn auth_for_session(
    state: &AppState,
    id: Uuid,
    headers: &HeaderMap,
) -> Result<(), (StatusCode, Json<ErrorResponse>)> {
    let sessions = state.sessions.read().await;
    let session = sessions
        .get(&id)
        .ok_or_else(|| (StatusCode::NOT_FOUND, json_err("unknown session")))?;
    if state.auth_mode == AuthMode::Required {
        let provided = extract_bearer(headers).ok_or_else(|| {
            (
                StatusCode::UNAUTHORIZED,
                json_err("missing or invalid authorization"),
            )
        })?;
        if !check_token(provided, &session.token) {
            return Err((
                StatusCode::UNAUTHORIZED,
                json_err("missing or invalid authorization"),
            ));
        }
    }
    Ok(())
}

fn json_err(msg: impl Into<String>) -> Json<ErrorResponse> {
    Json(ErrorResponse { error: msg.into() })
}

//! Evaluation error types.

use mlpl_core::LabeledShape;

/// Errors produced during evaluation.
#[derive(Clone, Debug, PartialEq)]
pub enum EvalError {
    /// No expressions to evaluate.
    EmptyInput,
    /// Variable not found in environment.
    UndefinedVariable(String),
    /// Feature not yet implemented.
    Unsupported(String),
    /// Error from array operations.
    ArrayError(mlpl_array::ArrayError),
    /// Repeat count must be a scalar.
    InvalidRepeatCount,
    /// Tensor constructor shape dimension must be a non-negative scalar integer.
    InvalidShapeDim,
    /// Error from built-in function dispatch.
    RuntimeError(mlpl_runtime::RuntimeError),
    /// Expected an array value but got a string.
    ExpectedArray,
    /// Expected a string value but got something else.
    ExpectedString,
    /// Saga R1 step 002: a CPU op tried to consume a
    /// `Value::DeviceTensor` whose bytes live on a
    /// peer server. Strict-fault: the user must
    /// explicitly `to_device('cpu', x)` to fetch.
    DeviceTensorFault {
        /// Peer URL the tensor lives on.
        peer: String,
        /// Device name on that peer (e.g., `"mlx"`).
        device: String,
    },
    /// Wrong number of arguments to a built-in.
    BadArity {
        /// Function name.
        func: String,
        /// Expected count.
        expected: usize,
        /// Got count.
        got: usize,
    },
    /// Error from the visualization layer.
    VizError(mlpl_viz::VizError),
    /// Two operand shapes (or labels) disagree in a way the named op
    /// cannot resolve. Saga 11.5 Phase 4: replaces string
    /// `Unsupported` messages for broadcasting and contraction
    /// failures. `expected` and `actual` are the left- and right-hand
    /// operand labeled shapes respectively.
    ShapeMismatch {
        /// Operator or builtin name (`"add"`, `"matmul"`, ...).
        op: String,
        /// Left-hand operand's labeled shape.
        expected: LabeledShape,
        /// Right-hand operand's labeled shape.
        actual: LabeledShape,
    },
    /// Two tensors (or a tensor and the active `device("...") { }`
    /// scope) disagree on device placement. Saga 14 step 005: raised
    /// by `apply(model, X)` when the input lives on a different
    /// device than the model's parameters, and by any op that
    /// receives mixed-device operands. `op` names the site
    /// (`"matmul"`, `"apply"`, `"add"`, ...); `expected` is the
    /// device the left-hand side carries and `actual` is the
    /// right-hand side's.
    DeviceMismatch {
        /// Operator or builtin name.
        op: String,
        /// Device the left-hand (or first) operand is on.
        expected: String,
        /// Device the right-hand (or second) operand is on.
        actual: String,
    },
    /// Saga 23 step 004: a typed-value consumer received an
    /// argument whose `ValueTag` does not satisfy the
    /// predicate. `expected` is the tag-display-name the
    /// consumer wants ("Logit", "Loss", ...), `actual` is the
    /// tag-display-name the argument carries, and `hint` is a
    /// 3-5 line tutoring message naming the most likely cause
    /// and one or two concrete fixes. Untagged arguments
    /// always pass and never raise this error (gradual-typing
    /// additivity).
    TypeMismatch {
        /// Consumer op name.
        op: String,
        /// Tag the consumer wants.
        expected: String,
        /// Tag the argument actually carries.
        actual: String,
        /// Tutoring hint (multi-line ASCII text).
        hint: String,
    },
    /// Saga 21.5 step 003: cooperative cancellation observed at a
    /// loop head or pre-builtin checkpoint. `step` is the
    /// inner-most loop iteration the eval was on when the trip was
    /// caught (`0` for non-loop sites). `partial_losses` is the
    /// per-iteration loss curve accumulated so far inside `train`
    /// (empty for `for` / `repeat` / pre-builtin sites). The
    /// session's `last_losses` binding is also populated with the
    /// same vector so post-cancel `:vars` still sees the partial
    /// curve.
    Cancelled {
        /// Iteration index at the trip site (0 for non-loop).
        step: usize,
        /// Per-iteration losses recorded so far inside `train`.
        partial_losses: Vec<f64>,
    },
    /// Saga 29 step 001: field access on a record that does not
    /// have the requested field. Lists the available keys so the
    /// user can fix the typo.
    FieldNotFound {
        /// Field name the user asked for.
        requested: String,
        /// Field names the record actually has, sorted.
        available: Vec<String>,
    },
    /// Saga 29 step 001: field access on a value that is not a
    /// record. The receiver_kind names the variant for the
    /// tutoring message ("array", "string", "model", etc.).
    FieldOnNonRecord {
        /// What kind of value the receiver was.
        receiver_kind: &'static str,
        /// Field name the user asked for.
        field: String,
    },
    /// Saga 29 step 002: a `[...]` array literal contained
    /// elements of more than one kind (e.g. mixing strings and
    /// numbers). The MLPL `[...]` literal is monomorphic: every
    /// element must evaluate to the same `Value` kind. `kinds`
    /// is the per-position list of `value_kind()` results, in
    /// source order, so the tutoring message can show which
    /// element broke the rule.
    MixedArrayLitElements {
        /// `value_kind()` of each element, in source order.
        kinds: Vec<&'static str>,
    },
    /// Saga 29 step 012: caller invoked `unwrap(r)` on an
    /// `Err(_)` value. The inner error payload's display
    /// form is recorded here so the user sees what went
    /// wrong rather than a generic "unwrap failed".
    UnwrapOnErr {
        /// Display-format of the Err payload.
        message: String,
    },
    /// Saga 29 step 012: caller invoked an Ok-only accessor
    /// (e.g. `unwrap`) on a non-Result value, or an Err-only
    /// accessor (`err_message`) on a non-Result.
    NotAResult {
        /// `value_kind()` of the receiver.
        receiver_kind: &'static str,
        /// Name of the accessor that was called.
        accessor: &'static str,
    },
}

impl std::fmt::Display for EvalError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::EmptyInput => write!(f, "empty input"),
            Self::UndefinedVariable(name) => write!(f, "undefined variable: {name}"),
            Self::InvalidRepeatCount => write!(f, "repeat count must be a scalar integer"),
            Self::InvalidShapeDim => {
                write!(f, "shape dimension must be a non-negative scalar integer")
            }
            Self::Unsupported(msg) => write!(f, "unsupported: {msg}"),
            Self::ArrayError(e) => write!(f, "array error: {e}"),
            Self::RuntimeError(e) => write!(f, "{e}"),
            Self::ExpectedArray => write!(f, "expected an array value, got a string"),
            Self::ExpectedString => write!(f, "expected a string value"),
            Self::DeviceTensorFault { peer, device } => {
                write!(
                    f,
                    "tensor lives on {peer}:{device}; use to_device('cpu', x) to fetch"
                )
            }
            Self::BadArity {
                func,
                expected,
                got,
            } => write!(f, "{func} expects {expected} arguments, got {got}"),
            Self::VizError(e) => write!(f, "{e}"),
            Self::ShapeMismatch {
                op,
                expected,
                actual,
            } => write!(f, "{op}: expected {expected}, got {actual}"),
            Self::DeviceMismatch {
                op,
                expected,
                actual,
            } => write!(f, "device mismatch: {op} on {expected} vs {actual}"),
            Self::TypeMismatch {
                op,
                expected,
                actual,
                hint,
            } => write!(
                f,
                "type mismatch in {op}: expected {expected}, got {actual}\n  hint: {hint}"
            ),
            Self::Cancelled { step, .. } => write!(f, "cancelled at step {step}"),
            Self::FieldNotFound {
                requested,
                available,
            } => write!(
                f,
                "record has no field '{requested}'; available: [{}]",
                available.join(", ")
            ),
            Self::FieldOnNonRecord {
                receiver_kind,
                field,
            } => write!(
                f,
                "field access '.{field}' requires a record receiver, got {receiver_kind}"
            ),
            Self::MixedArrayLitElements { kinds } => write!(
                f,
                "[...] array literal must be all-strings or all-numbers; got mixed kinds: [{}]",
                kinds.join(", ")
            ),
            Self::UnwrapOnErr { message } => {
                write!(f, "unwrap on an Err value: {message}")
            }
            Self::NotAResult {
                receiver_kind,
                accessor,
            } => write!(
                f,
                "{accessor}: expected a Result value, got {receiver_kind}"
            ),
        }
    }
}

impl std::error::Error for EvalError {}

impl From<mlpl_array::ArrayError> for EvalError {
    fn from(e: mlpl_array::ArrayError) -> Self {
        Self::ArrayError(e)
    }
}

impl From<mlpl_runtime::RuntimeError> for EvalError {
    fn from(e: mlpl_runtime::RuntimeError) -> Self {
        Self::RuntimeError(e)
    }
}

impl From<mlpl_viz::VizError> for EvalError {
    fn from(e: mlpl_viz::VizError) -> Self {
        Self::VizError(e)
    }
}

