1	//! Tape-side lowering of the Saga 11 model DSL.
2	//!
3	//! This is the autograd twin of `model_dispatch::apply_model`: given
4	//! a `ModelSpec` and an input `Tensor` handle, it walks the model
5	//! tree and emits the same primitive ops onto the autograd tape so
6	//! that `grad(loss_with_apply, ...)` -- and therefore every optimizer
7	//! built on top of it -- can route gradients back to each layer's
8	//! trainable parameter leaves.
9	//!
10	//! Coverage today:
11	//!
12	//! - `linear`, `chain`, activation layers, `residual`, `rms_norm`,
13	//!   and single-head `attention` are fully lowered.
14	//! - Multi-head attention (`heads > 1`) is not yet supported; the
15	//!   per-head slicing it needs is not expressible with the current
16	//!   `Tensor` op surface. Use `heads = 1` or inline the per-head
17	//!   forward pass in the loss expression for now.
18	
19	use std::collections::HashMap;
20	use std::rc::Rc;
21	
22	use mlpl_array::{DenseArray, Shape};
23	use mlpl_autograd::{Tape, Tensor};
24	
25	use crate::error::EvalError;
26	use crate::model::{ActKind, ModelSpec};
27	
28	/// Tape-side analogue of `model_dispatch::apply_model`. Walks the
29	/// model and emits the matching primitive ops on the autograd tape.
30	pub(crate) fn apply_model_tape(
31	    model: &ModelSpec,
32	    x: Tensor,
33	    tape: &Rc<Tape>,
34	    params: &HashMap<String, Tensor>,
35	) -> Result<Tensor, EvalError> {
36	    match model {
37	        ModelSpec::Linear { w, b } => linear_tape(&x, w, b, tape, params),
38	        ModelSpec::Chain(children) => {
39	            let mut cur = x;
40	            for child in children {
41	                cur = apply_model_tape(child, cur, tape, params)?;
42	            }
43	            Ok(cur)
44	        }
45	        ModelSpec::Activation(kind) => Ok(match kind {
46	            ActKind::Tanh => x.tanh(),
47	            ActKind::Relu => x.relu(),
48	            ActKind::Softmax => x.softmax(),
49	        }),
50	        ModelSpec::Residual(inner) => {
51	            let inner_out = apply_model_tape(inner, x.clone(), tape, params)?;
52	            Ok(x.add(&inner_out))
53	        }
54	        ModelSpec::RmsNorm { .. } => rms_norm_tape(&x, tape),
55	        ModelSpec::Embedding { table, vocab, .. } => {
56	            let table_t = params
57	                .get(table)
58	                .cloned()
59	                .ok_or_else(|| EvalError::UndefinedVariable(table.clone()))?;
60	            // The token id array enters the tape as a non-trainable
61	            // input leaf; we use its eager value to build a one-hot
62	            // matrix and matmul against the trainable table tensor.
63	            // Backprop then routes through matmul straight into the
64	            // table's gradient buffer.
65	            let tokens_arr = x.value().clone();
66	            let onehot_arr = onehot_from_tokens(&tokens_arr, *vocab)?;
67	            let onehot_t = Tensor::leaf(Rc::clone(tape), onehot_arr, false);
68	            Ok(onehot_t.matmul(&table_t))
69	        }
70	        ModelSpec::Attention {
71	            wq,
72	            wk,
73	            wv,
74	            wo,
75	            d_model,
76	            heads,
77	            causal,
78	        } => {
79	            if *heads != 1 {
80	                return Err(EvalError::Unsupported(format!(
81	                    "grad: apply() through multi-head attention (heads={heads}) is not \
82	                     yet supported on the autograd tape; use heads=1 or inline the \
83	                     per-head forward pass in the loss expression"
84	                )));
85	            }
86	            let inputs = AttentionInputs {
87	                wq,
88	                wk,
89	                wv,
90	                wo,
91	                d_model: *d_model,
92	                causal: *causal,
93	            };
94	            attention_single_head_tape(&x, &inputs, tape, params)
95	        }
96	        ModelSpec::LinearLora {
97	            w,
98	            b,
99	            a,
100	            b_adapter,
101	            rank,
102	            alpha,
103	            ..
104	        } => linear_lora_tape(
105	            &x,
106	            &LinearLoraTapeInputs {
107	                w,
108	                b,
109	                a,
110	                b_adapter,
111	                rank: *rank,
112	                alpha: *alpha,
113	            },
114	            tape,
115	            params,
116	        ),
117	    }
118	}
119	
120	/// Named-field inputs for one `linear_lora_tape` call so
121	/// the helper stays at 4 args and does not trip
122	/// `clippy::too_many_arguments`.
123	struct LinearLoraTapeInputs<'a> {
124	    w: &'a str,
125	    b: &'a str,
126	    a: &'a str,
127	    b_adapter: &'a str,
128	    rank: usize,
129	    alpha: f64,
130	}
131	
132	fn linear_lora_tape(
133	    x: &Tensor,
134	    inputs: &LinearLoraTapeInputs<'_>,
135	    tape: &Rc<Tape>,
136	    params: &HashMap<String, Tensor>,
137	) -> Result<Tensor, EvalError> {
138	    let w_t = params
139	        .get(inputs.w)
140	        .cloned()
141	        .ok_or_else(|| EvalError::UndefinedVariable(inputs.w.into()))?;
142	    let b_t = params
143	        .get(inputs.b)
144	        .cloned()
145	        .ok_or_else(|| EvalError::UndefinedVariable(inputs.b.into()))?;
146	    let a_t = params
147	        .get(inputs.a)
148	        .cloned()
149	        .ok_or_else(|| EvalError::UndefinedVariable(inputs.a.into()))?;
150	    let b_adapt_t = params
151	        .get(inputs.b_adapter)
152	        .cloned()
153	        .ok_or_else(|| EvalError::UndefinedVariable(inputs.b_adapter.into()))?;
154	    // Base: X @ W
155	    let xw = x.matmul(&w_t);
156	    // Adapter: (alpha / rank) * X @ A @ B
157	    let xa = x.matmul(&a_t);
158	    let xab = xa.matmul(&b_adapt_t);
159	    let scale = inputs.alpha / inputs.rank as f64;
160	    let scale_t = Tensor::leaf(Rc::clone(tape), DenseArray::from_scalar(scale), false);
161	    let xab_scaled = xab.mul(&scale_t);
162	    // Bias: broadcast [1, out] -> [n, out] via ones([n, 1]) @ b.
163	    let n = xw.value().shape().dims()[0];
164	    let ones_arr = DenseArray::new(Shape::new(vec![n, 1]), vec![1.0; n])?;
165	    let ones_t = Tensor::leaf(Rc::clone(tape), ones_arr, false);
166	    Ok(xw.add(&xab_scaled).add(&ones_t.matmul(&b_t)))
167	}
168	
169	fn linear_tape(
170	    x: &Tensor,
171	    w: &str,
172	    b: &str,
173	    tape: &Rc<Tape>,
174	    params: &HashMap<String, Tensor>,
175	) -> Result<Tensor, EvalError> {
176	    let w_t = params
177	        .get(w)
178	        .cloned()
179	        .ok_or_else(|| EvalError::UndefinedVariable(w.into()))?;
180	    let b_t = params
181	        .get(b)
182	        .cloned()
183	        .ok_or_else(|| EvalError::UndefinedVariable(b.into()))?;
184	    let xw = x.matmul(&w_t);
185	    // b is [1, out]; lift to [n, out] via ones([n, 1]) @ b so the
186	    // tape graph matches the hand-rolled broadcast form exactly.
187	    let n = xw.value().shape().dims()[0];
188	    let ones_arr = DenseArray::new(Shape::new(vec![n, 1]), vec![1.0; n])?;
189	    let ones_t = Tensor::leaf(Rc::clone(tape), ones_arr, false);
190	    Ok(xw.add(&ones_t.matmul(&b_t)))
191	}
192	
193	/// Per-row RMS normalization on the tape:
194	/// `y[i, :] = x[i, :] / sqrt(mean(x[i, :]^2) + eps)`.
195	/// `sqrt(v)` is encoded as `exp(-0.5 * log(v))` because the tape
196	/// does not yet expose a direct sqrt op. Per-row mean is encoded as
197	/// `matmul(x, ones([cols, 1])) / cols`, and the broadcast back to
198	/// `[rows, cols]` as `rsqrt @ ones([1, cols])`.
199	fn rms_norm_tape(x: &Tensor, tape: &Rc<Tape>) -> Result<Tensor, EvalError> {
200	    let dims = x.value().shape().dims().to_vec();
201	    if dims.len() != 2 {
202	        return Err(EvalError::Unsupported(
203	            "rms_norm: input must be a rank-2 [rows, cols] matrix".into(),
204	        ));
205	    }
206	    let cols = dims[1];
207	    let eps = 1e-8_f64;
208	    let leaf = |v: DenseArray| Tensor::leaf(Rc::clone(tape), v, false);
209	    let ones_col = leaf(DenseArray::new(Shape::new(vec![cols, 1]), vec![1.0; cols])?);
210	    let ones_row = leaf(DenseArray::new(Shape::new(vec![1, cols]), vec![1.0; cols])?);
211	    let inv_cols = leaf(DenseArray::from_scalar(1.0 / cols as f64));
212	    let eps_t = leaf(DenseArray::from_scalar(eps));
213	    let half_neg = leaf(DenseArray::from_scalar(-0.5));
214	    let row_mean_eps = x.mul(x).matmul(&ones_col).mul(&inv_cols).add(&eps_t);
215	    let rsqrt = row_mean_eps.log().mul(&half_neg).exp();
216	    Ok(x.mul(&rsqrt.matmul(&ones_row)))
217	}
218	
219	/// One-hot encode a 1-D token id array `[N]` into `[N, vocab]`. Mirrors
220	/// the eager helper in `model_dispatch` so the tape sees an identical
221	/// matrix; consolidating the two would couple the modules more tightly
222	/// than this small allocation is worth.
223	fn onehot_from_tokens(tokens: &DenseArray, vocab: usize) -> Result<DenseArray, EvalError> {
224	    let dims = tokens.shape().dims();
225	    if dims.len() != 1 {
226	        return Err(EvalError::Unsupported(format!(
227	            "embed (tape): tokens must be a 1-D [N] array, got shape {dims:?}"
228	        )));
229	    }
230	    let n = dims[0];
231	    let mut data = vec![0.0_f64; n * vocab];
232	    for (row, &id_f) in tokens.data().iter().enumerate() {
233	        if !id_f.is_finite() || id_f < 0.0 || id_f.fract() != 0.0 {
234	            return Err(EvalError::Unsupported(format!(
235	                "embed (tape): token at position {row} = {id_f} is not a non-negative integer"
236	            )));
237	        }
238	        let id = id_f as usize;
239	        if id >= vocab {
240	            return Err(EvalError::Unsupported(format!(
241	                "embed (tape): token at position {row} = {id} out of vocab range [0, {vocab})"
242	            )));
243	        }
244	        data[row * vocab + id] = 1.0;
245	    }
246	    DenseArray::new(Shape::new(vec![n, vocab]), data).map_err(|e| {
247	        EvalError::Unsupported(format!("embed (tape): one-hot construction failed: {e}"))
248	    })
249	}
250	
251	/// Bundle of attention parameter names + model dimension so the
252	/// tape helper stays inside the 7-arg clippy budget without needing
253	/// `#[allow(clippy::too_many_arguments)]`.
254	struct AttentionInputs<'a> {
255	    wq: &'a str,
256	    wk: &'a str,
257	    wv: &'a str,
258	    wo: &'a str,
259	    d_model: usize,
260	    causal: bool,
261	}
262	
263	/// Single-head scaled-dot-product attention on the tape. Multi-head
264	/// requires slicing that the autograd substrate does not yet expose.
265	///
266	/// Saga 29 step 008: accept rank-3 `[B, T, d_model]` by lowering as
267	/// `B` rank-2 attention chains and stitching the per-batch outputs
268	/// back via `take` + `reshape(_, [1, T, d_model])` + chained
269	/// `concat(..., axis=0)`. The chain is `O(B)` concat depth but every
270	/// constituent op (`take`, `reshape`, `concat`) is already on the
271	/// tape, so no new tape primitive is needed.
272	fn attention_single_head_tape(
273	    x: &Tensor,
274	    inputs: &AttentionInputs<'_>,
275	    tape: &Rc<Tape>,
276	    params: &HashMap<String, Tensor>,
277	) -> Result<Tensor, EvalError> {
278	    let dims = x.value().shape().dims().to_vec();
279	    if dims.len() == 3 && dims[2] == inputs.d_model {
280	        return attention_single_head_tape_rank3(x, inputs, tape, params, dims);
281	    }
282	    if dims.len() != 2 || dims[1] != inputs.d_model {
283	        return Err(EvalError::Unsupported(format!(
284	            "attention: input must be [seq, {}] or [B, T, {}], got {dims:?}",
285	            inputs.d_model, inputs.d_model
286	        )));
287	    }
288	    attention_single_head_tape_rank2(x, inputs, tape, params)
289	}
290	
291	fn attention_single_head_tape_rank2(
292	    x: &Tensor,
293	    inputs: &AttentionInputs<'_>,
294	    tape: &Rc<Tape>,
295	    params: &HashMap<String, Tensor>,
296	) -> Result<Tensor, EvalError> {
297	    let fetch = |name: &str| -> Result<Tensor, EvalError> {
298	        params
299	            .get(name)
300	            .cloned()
301	            .ok_or_else(|| EvalError::UndefinedVariable(name.into()))
302	    };
303	    let wq_t = fetch(inputs.wq)?;
304	    let wk_t = fetch(inputs.wk)?;
305	    let wv_t = fetch(inputs.wv)?;
306	    let wo_t = fetch(inputs.wo)?;
307	    let q = x.matmul(&wq_t);
308	    let k = x.matmul(&wk_t);
309	    let v = x.matmul(&wv_t);
310	    let scale = Tensor::leaf(
311	        Rc::clone(tape),
312	        DenseArray::from_scalar(1.0 / (inputs.d_model as f64).sqrt()),
313	        false,
314	    );
315	    let scores = q.matmul(&k.transpose()).mul(&scale);
316	    let masked = if inputs.causal {
317	        let seq = scores.value().shape().dims()[0];
318	        let mask = Tensor::leaf(Rc::clone(tape), causal_mask_array(seq)?, false);
319	        scores.add(&mask)
320	    } else {
321	        scores
322	    };
323	    Ok(masked.softmax().matmul(&v).matmul(&wo_t))
324	}
325	
326	fn attention_single_head_tape_rank3(
327	    x: &Tensor,
328	    inputs: &AttentionInputs<'_>,
329	    tape: &Rc<Tape>,
330	    params: &HashMap<String, Tensor>,
331	    dims: Vec<usize>,
332	) -> Result<Tensor, EvalError> {
333	    let (batch, t, d) = (dims[0], dims[1], dims[2]);
334	    let mut acc: Option<Tensor> = None;
335	    for b in 0..batch {
336	        let x_b = x.take(0, b);
337	        let out_b = attention_single_head_tape_rank2(&x_b, inputs, tape, params)?;
338	        let out_b_3 = out_b.reshape(mlpl_array::Shape::new(vec![1, t, d]));
339	        acc = Some(match acc {
340	            None => out_b_3,
341	            Some(prev) => prev.concat(&out_b_3, 0),
342	        });
343	    }
344	    acc.ok_or_else(|| {
345	        EvalError::Unsupported("attention: rank-3 input had zero batch entries".into())
346	    })
347	}
348	
349	/// Build a `[seq, seq]` additive causal mask: zero on and below the
350	/// diagonal, a large negative value strictly above. Adding it to the
351	/// pre-softmax scores pushes non-causal positions to ~0 probability
352	/// after softmax, without introducing a new tape primitive.
353	fn causal_mask_array(seq: usize) -> Result<DenseArray, EvalError> {
354	    let neg = -1.0e9_f64;
355	    let mut data = vec![0.0_f64; seq * seq];
356	    for r in 0..seq {
357	        for c in (r + 1)..seq {
358	            data[r * seq + c] = neg;
359	        }
360	    }
361	    Ok(DenseArray::new(Shape::new(vec![seq, seq]), data)?)
362	}
363	
364	/// Shape + index validation for `cross_entropy(logits, targets)`.
365	/// Shared between the forward-only runtime builtin path (via `eval.rs`)
366	/// and the tape-side path in `grad.rs`, so errors look identical either
367	/// way. Returns a flat `Vec<usize>` of class indices ready to hand to
368	/// `Tensor::cross_entropy`.
369	pub(crate) fn validate_cross_entropy_targets(
370	    logits: &DenseArray,
371	    targets: &DenseArray,
372	) -> Result<Vec<usize>, EvalError> {
373	    let dims = logits.shape().dims();
374	    let (n, v) = match dims.len() {
375	        2 => (dims[0], dims[1]),
376	        3 => (dims[0] * dims[1], dims[2]),
377	        r => {
378	            return Err(EvalError::Unsupported(format!(
379	                "cross_entropy: logits must be rank 2 or 3, got rank {r}"
380	            )));
381	        }
382	    };
383	    if targets.elem_count() != n {
384	        return Err(EvalError::ShapeMismatch {
385	            op: "cross_entropy".into(),
386	            expected: mlpl_core::LabeledShape::new(vec![n], vec![None]),
387	            actual: mlpl_core::LabeledShape::new(
388	                targets.shape().dims().to_vec(),
389	                vec![None; targets.rank()],
390	            ),
391	        });
392	    }
393	    let mut idx = Vec::with_capacity(n);
394	    for (i, &t) in targets.data().iter().enumerate() {
395	        if t < 0.0 || t.fract() != 0.0 || (t as usize) >= v {
396	            return Err(EvalError::Unsupported(format!(
397	                "cross_entropy: target[{i}] = {t} is not a valid class index in 0..{v}"
398	            )));
399	        }
400	        idx.push(t as usize);
401	    }
402	    Ok(idx)
403	}
