fn compute_attn_weights(
    x: &DenseArray,
    wq: &str,
    wk: &str,
    d_model: usize,
    heads: usize,
    causal: bool,
    env: &Environment,
) -> Result<DenseArray, EvalError> {
    let dims = x.shape().dims();
    // Saga 29 step 008: rank-3 [B, T, d_model] -> stack the
    // per-batch single-head weights into [B, T, T]. Multi-
    // head + rank-3 still rejects; that combination lands in
    // step 010.
    if dims.len() == 3 && dims[2] == d_model {
        if heads != 1 {
            return Err(EvalError::Unsupported(format!(
                "attention_weights: rank-3 batched input is only supported for \
                 heads=1 right now (got heads={heads}); use heads=1 or fold the \
                 batch dim manually until multi-head tape lowering lands"
            )));
        }
        let (batch, t) = (dims[0], dims[1]);
        let mut data = Vec::with_capacity(batch * t * t);
        for b in 0..batch {
            let x_b = x.take(0, b)?;
            data.extend_from_slice(
                compute_attn_weights(&x_b, wq, wk, d_model, heads, causal, env)?.data(),
            );
        }
        return Ok(DenseArray::new(Shape::new(vec![batch, t, t]), data)?);
    }
    if dims.len() != 2 || dims[1] != d_model {
        return Err(EvalError::Unsupported(format!(
            "attention_weights: input must be [seq, {d_model}] or [B, T, {d_model}], got {:?}",
            dims
        )));
    }
    let seq = dims[0];
    let d_k = d_model / heads;
    let wq_a = env
        .get(wq)
        .ok_or_else(|| EvalError::UndefinedVariable(wq.into()))?;
    let wk_a = env
        .get(wk)
        .ok_or_else(|| EvalError::UndefinedVariable(wk.into()))?;
    let q = crate::device::dispatched_call(env, "matmul", vec![x.clone(), wq_a.clone()])?;
    let k = crate::device::dispatched_call(env, "matmul", vec![x.clone(), wk_a.clone()])?;
    let scale = 1.0 / (d_k as f64).sqrt();
    let mut all = Vec::with_capacity(heads * seq * seq);
    for h in 0..heads {
        let attn = attn_head_weights(&q, &k, h, d_k, seq, scale, causal, env)?;
        all.extend_from_slice(attn.data());
    }
    let shape = if heads == 1 {
        vec![seq, seq]
    } else {
        vec![heads, seq, seq]
    };
    Ok(DenseArray::new(Shape::new(shape), all)?)
}

// Tape lowering of the model DSL lives in `crate::model_tape`; the
// eager forward pass below stays here.

