fn run_demo(demo_name: &str, lines: &[&str]) -> Result<(), String> {
    let mut env = Environment::new();
    for (i, line) in lines.iter().enumerate() {
        let trimmed = line.trim();
        if trimmed.is_empty()
            || trimmed.starts_with("//")
            || trimmed.starts_with('#')
            || (trimmed.starts_with(':') && !trimmed.starts_with("::"))
