1	use std::cell::RefCell;
2	use std::rc::Rc;
3	
4	use mlpl_wasm::WasmSession;
5	use web_sys::{HtmlInputElement, KeyboardEvent};
6	use yew::prelude::*;
7	
8	use crate::demos::DEMOS;
9	use crate::help::help_text;
10	use crate::state::{EntryKind, HistoryEntry};
11	
12	pub fn toggle_bool(handle: UseStateHandle<bool>, value: bool) -> Callback<web_sys::MouseEvent> {
13	    Callback::from(move |_| handle.set(value))
14	}
15	
16	#[derive(Clone)]
17	pub struct EvalDeps {
18	    pub session: Rc<RefCell<WasmSession>>,
19	    pub history: UseStateHandle<Vec<HistoryEntry>>,
20	    pub input_value: UseStateHandle<String>,
21	    pub cmd_history: UseStateHandle<Vec<String>>,
22	    pub cmd_index: UseStateHandle<Option<usize>>,
23	}
24	
25	/// Single-line submit: thin wrapper that pipes the line through
26	/// the batch path so there is exactly one place that mutates
27	/// state. Calling `make_submit` N times in a tight loop USED
28	/// to drop N-1 history entries because each call did
29	/// `(*deps.history).clone()` -> push one -> `set(new)` --
30	/// inside one event tick every clone read the same snapshot
31	/// and only the last `set` won (Tutorial Run-All bug, May 7
32	/// 2026). Routing through `make_submit_batch` collapses any
33	/// number of lines into a single read-modify-write.
34	pub fn make_submit(deps: EvalDeps) -> Callback<String> {
35	    let batch = make_submit_batch(deps);
36	    Callback::from(move |line: String| batch.emit(vec![line]))
37	}
38	
39	/// Evaluate every line in `lines` against the current session
40	/// in one pass, then commit all four state handles exactly
41	/// once. Empty/whitespace-only lines are skipped (matching
42	/// single-line submit semantics); `:clear` and `:help` are
43	/// honored mid-batch.
44	pub fn make_submit_batch(deps: EvalDeps) -> Callback<Vec<String>> {
45	    Callback::from(move |lines: Vec<String>| {
46	        let mut new_history = (*deps.history).clone();
47	        let mut new_cmds = (*deps.cmd_history).clone();
48	        let mut any = false;
49	        for line in lines {
50	            let trimmed = line.trim();
51	            if trimmed.is_empty() {
52	                continue;
53	            }
54	            any = true;
55	            new_cmds.push(trimmed.to_string());
56	            if trimmed == ":clear" {
57	                deps.session.borrow().clear();
58	                new_history.clear();
59	                continue;
60	            }
61	            let entry = if trimmed == ":help" {
62	                HistoryEntry {
63	                    input: trimmed.to_string(),
64	                    output: help_text(),
65	                    is_error: false,
66	                    kind: EntryKind::Command,
67	                }
68	            } else {
69	                let result = deps.session.borrow().eval(trimmed);
70	                let is_error = result.starts_with("error:");
71	                HistoryEntry {
72	                    input: trimmed.to_string(),
73	                    output: result,
74	                    is_error,
75	                    kind: EntryKind::Command,
76	                }
77	            };
78	            new_history.push(entry);
79	        }
80	        if !any {
81	            return;
82	        }
83	        deps.history.set(new_history);
84	        deps.cmd_history.set(new_cmds);
85	        deps.cmd_index.set(None);
86	        deps.input_value.set(String::new());
87	    })
88	}
89	
90	pub fn make_clear(
91	    session: Rc<RefCell<WasmSession>>,
92	    history: UseStateHandle<Vec<HistoryEntry>>,
93	) -> Callback<web_sys::MouseEvent> {
94	    Callback::from(move |_| {
95	        session.borrow().clear();
96	        history.set(Vec::new());
97	    })
98	}
99	
100	pub fn make_run_demo(
101	    session: Rc<RefCell<WasmSession>>,
102	    history: UseStateHandle<Vec<HistoryEntry>>,
103	) -> Callback<usize> {
104	    Callback::from(move |idx: usize| {
105	        let Some(demo) = DEMOS.get(idx) else {
106	            return;
107	        };
108	        session.borrow().clear();
109	        // Lead with a narration panel framing what the demo does
110	        // and why. Demo lines follow; the takeaway narration lands
111	        // after the final line in `schedule_demo_line`. Also bind
112	        // a `_demo` string in the session so `:describe _demo`
113	        // prints the intro + takeaway from the REPL.
114	        bind_demo_metadata(&session.borrow(), demo);
115	        let intro_entry = HistoryEntry {
116	            input: format!("About this demo -- {}", demo.name),
117	            output: demo.intro.to_string(),
118	            is_error: false,
119	            kind: EntryKind::Narration,
120	        };
121	        let entries = vec![intro_entry];
122	        history.set(entries.clone());
123	        // Evaluate demo lines asynchronously: each line runs in
124	        // its own `Timeout::new(0, ...)` tick so the browser can
125	        // paint the preceding line's output and process input
126	        // between lines. A long-running single line (e.g. `train
127	        // 30 { ... }`) still blocks the event loop *during* its
128	        // own eval -- fixing that needs Web Workers (see
129	        // docs/worker-threads.md) -- but the cross-line yield
130	        // keeps the tab from triggering the "unresponsive"
131	        // dialog on multi-line demos where the total wall clock
132	        // is the problem.
133	        //
134	        // We thread the accumulated `entries` vec through
135	        // recursion explicitly rather than reading from the
136	        // `UseStateHandle` inside each tick: a state handle is
137	        // snapshotted at the callback's closure-creation time
138	        // and does not refresh between `set()` calls, so reading
139	        // via `(*history).clone()` inside a deferred Timeout
140	        // reliably sees the stale initial value and each tick
141	        // overwrites the previous one's write. Passing `entries`
142	        // by move keeps a single authoritative Rust-side source
