                Some("channel".into()),
                Some("y".into()),
                Some("x".into()),
            ])
            .map_err(|e| JsValue::from_str(&format!("{e}")))?;
        self.env.borrow_mut().set(name.into(), arr);
        Ok(())
    }
}

