            decode_image_to_session(&img_clone, &session_clone, &history_clone, &name_clone)
        {
            session_clone
                .borrow()
                .bind_upload_result_err(&name_clone, "decode failed");
            push_error(&history_clone, &name_clone, &format!("{err:?}"));
        }
    }) as Box<dyn FnMut(Event)>);
