                chw[c * h * w + y * w + x] = v / 127.5 - 1.0;
            }
        }
    }
    session
        .borrow()
        .bind_upload_result_ok(name, &chw, TARGET_H, TARGET_W)?;
    push_success(history, name, src_w, src_h);
    Ok(())
