fn push_error(history: &UseStateHandle<Vec<HistoryEntry>>, name: &str, msg: &str) {
    let mut entries: Vec<HistoryEntry> = (**history).clone();
    entries.push(HistoryEntry {
        input: format!("Image upload failed ({name})"),
        output: format!(
            "{msg}\n\n`{name}` is bound to `Err(\"decode failed\")` -- inspect via `err_message({name})`.",
        ),
        is_error: true,
        kind: EntryKind::Narration,
    });
    history.set(entries);
