1	//! Client-side image upload via the browser's File / Image /
2	//! Canvas APIs. Saga 29 step 011 follow-up; step 016 rework.
3	//!
4	//! Two entry points share the same Canvas decode + resize
5	//! pipeline:
6	//!
7	//! 1. **Button-bound upload** (`make_upload_image`). Wired to
8	//!    a file `<input type="file">`'s `onchange` event. The
9	//!    chosen image binds under the name resolved from
10	//!    `pending_name`: `Some(name)` if a `:upload <name>` REPL
11	//!    command triggered the picker programmatically, else the
12	//!    default `"uploaded"` (the legacy button click).
13	//!
14	//! 2. **`:upload x` REPL command** (Saga 29 step 016). Routed
15	//!    in `handlers.rs::make_submit_batch`: setting
16	//!    `pending_name` to `Some("x")` and programmatically
17	//!    clicking the file input. The handler stays in the
18	//!    synchronous chain of the user's Enter keypress, so the
19	//!    browser accepts the `click()` as a user gesture.
20	//!
21	//! Either way, the uploaded image lands as a `Value::Result`
22	//! in the WASM session: `Ok({pixels: [1, 3, 64, 64], h: 64,
23	//! w: 64})` on success, `Err("cancelled")` if the picker is
24	//! dismissed, `Err("...")` for any decode/resize failure.
25	//! `:upload x` becomes the first in-tree consumer of the
26	//! `Value::Result` type shipped in Saga 29 step 012.
27	
28	use std::cell::RefCell;
29	use std::rc::Rc;
30	
31	use mlpl_wasm::WasmSession;
32	use wasm_bindgen::{JsCast, JsValue, closure::Closure};
33	use web_sys::{
34	    CanvasRenderingContext2d, Event, FileReader, HtmlCanvasElement, HtmlImageElement,
35	    HtmlInputElement, ImageData,
36	};
37	use yew::prelude::*;
38	
39	use crate::state::{EntryKind, HistoryEntry};
40	
41	const TARGET_H: u32 = 64;
42	const TARGET_W: u32 = 64;
43	const DEFAULT_NAME: &str = "uploaded";
44	
45	/// Caller-chosen variable name for the next upload binding.
46	/// `None` = the legacy button-click path (binds `"uploaded"`).
47	/// `Some(name)` = the `:upload <name>` REPL path.
48	pub type PendingUploadName = UseStateHandle<Option<String>>;
49	
50	pub fn make_upload_image(
51	    session: Rc<RefCell<WasmSession>>,
52	    history: UseStateHandle<Vec<HistoryEntry>>,
53	    pending_name: PendingUploadName,
54	) -> Callback<Event> {
55	    Callback::from(move |e: Event| {
56	        let target: HtmlInputElement = match e.target_dyn_into() {
57	            Some(t) => t,
58	            None => return,
59	        };
60	        let files = match target.files() {
61	            Some(f) => f,
62	            None => return,
63	        };
64	        if files.length() == 0 {
65	            return;
66	        }
67	        let file = match files.get(0) {
68	            Some(f) => f,
69	            None => return,
70	        };
71	        let name = pending_name
72	            .as_ref()
73	            .map_or_else(|| DEFAULT_NAME.to_string(), Clone::clone);
74	        pending_name.set(None);
75	        if let Err(err) = start_read(&file, &session, &history, &name) {
76	            session
77	                .borrow()
78	                .bind_upload_result_err(&name, "decode-init failed");
79	            push_error(&history, &name, &format!("{err:?}"));
80	        }
81	        // Reset so re-selecting the same file fires `change` again.
82	        target.set_value("");
83	    })
84	}
85	
86	/// Saga 29 step 016: cancel handler for the `<input type=file>`'s
87	/// `cancel` event. Wires `Err("cancelled")` under the pending
88	/// variable name (if any) so a `:upload x` command leaves
89	/// `x = Err("cancelled")` instead of an undefined variable.
90	pub fn make_upload_cancel(
91	    session: Rc<RefCell<WasmSession>>,
92	    history: UseStateHandle<Vec<HistoryEntry>>,
93	    pending_name: PendingUploadName,
94	) -> Callback<Event> {
95	    Callback::from(move |_: Event| {
96	        let name = pending_name
97	            .as_ref()
98	            .map_or_else(|| DEFAULT_NAME.to_string(), Clone::clone);
99	        pending_name.set(None);
100	        session.borrow().bind_upload_result_err(&name, "cancelled");
101	        push_cancel(&history, &name);
102	    })
103	}
104	
105	fn start_read(
106	    file: &web_sys::File,
107	    session: &Rc<RefCell<WasmSession>>,
108	    history: &UseStateHandle<Vec<HistoryEntry>>,
109	    name: &str,
110	) -> Result<(), JsValue> {
111	    let reader = FileReader::new()?;
112	    let reader_clone = reader.clone();
113	    let session_clone = session.clone();
114	    let history_clone = history.clone();
115	    let name_clone = name.to_string();
116	    let onload = Closure::wrap(Box::new(move |_: Event| match reader_clone.result() {
117	        Ok(v) => match v.as_string() {
118	            Some(url) => {
119	                if let Err(err) =
120	                    start_image_load(&url, &session_clone, &history_clone, &name_clone)
121	                {
122	                    session_clone
123	                        .borrow()
124	                        .bind_upload_result_err(&name_clone, "image-load failed");
125	                    push_error(&history_clone, &name_clone, &format!("{err:?}"));
126	                }
127	            }
128	            None => push_error(
129	                &history_clone,
130	                &name_clone,
131	                "FileReader result was not a string",
132	            ),
133	        },
134	        Err(err) => push_error(&history_clone, &name_clone, &format!("{err:?}")),
135	    }) as Box<dyn FnMut(Event)>);
136	    reader.set_onload(Some(onload.as_ref().unchecked_ref()));
137	    onload.forget();
138	    reader.read_as_data_url(file)?;
139	    Ok(())
140	}
141	
142	fn start_image_load(
143	    url: &str,
144	    session: &Rc<RefCell<WasmSession>>,
145	    history: &UseStateHandle<Vec<HistoryEntry>>,
146	    name: &str,
147	) -> Result<(), JsValue> {
148	    let img = HtmlImageElement::new()?;
149	    let img_clone = img.clone();
150	    let session_clone = session.clone();
151	    let history_clone = history.clone();
152	    let name_clone = name.to_string();
153	    let onload = Closure::wrap(Box::new(move |_: Event| {
154	        if let Err(err) =
155	            decode_image_to_session(&img_clone, &session_clone, &history_clone, &name_clone)
156	        {
157	            session_clone
158	                .borrow()
159	                .bind_upload_result_err(&name_clone, "decode failed");
160	            push_error(&history_clone, &name_clone, &format!("{err:?}"));
161	        }
162	    }) as Box<dyn FnMut(Event)>);
163	    img.set_onload(Some(onload.as_ref().unchecked_ref()));
164	    onload.forget();
165	    img.set_src(url);
166	    Ok(())
167	}
168	
169	fn decode_image_to_session(
170	    img: &HtmlImageElement,
171	    session: &Rc<RefCell<WasmSession>>,
172	    history: &UseStateHandle<Vec<HistoryEntry>>,
173	    name: &str,
174	) -> Result<(), JsValue> {
175	    let src_w = img.natural_width();
176	    let src_h = img.natural_height();
177	    let document = web_sys::window()
178	        .ok_or_else(|| JsValue::from_str("no window"))?
179	        .document()
180	        .ok_or_else(|| JsValue::from_str("no document"))?;
181	    let canvas: HtmlCanvasElement = document
