34	/// Single-line submit: thin wrapper that pipes the line through
35	/// the batch path so there is exactly one place that mutates
36	/// state. Calling `make_submit` N times in a tight loop USED
37	/// to drop N-1 history entries because each call did
38	/// `(*deps.history).clone()` -> push one -> `set(new)` --
39	/// inside one event tick every clone read the same snapshot
40	/// and only the last `set` won (Tutorial Run-All bug, May 7
41	/// 2026). Routing through `make_submit_batch` collapses any
42	/// number of lines into a single read-modify-write.
43	pub fn make_submit(deps: EvalDeps) -> Callback<String> {
44	    let batch = make_submit_batch(deps);
45	    Callback::from(move |line: String| batch.emit(vec![line]))
46	}
47	
48	/// Evaluate every line in `lines` against the current session
49	/// in one pass, then commit all four state handles exactly
50	/// once. Empty/whitespace-only lines are skipped (matching
51	/// single-line submit semantics); `:clear` and `:help` are
52	/// honored mid-batch.
53	pub fn make_submit_batch(deps: EvalDeps) -> Callback<Vec<String>> {
54	    Callback::from(move |lines: Vec<String>| {
55	        let mut new_history = (*deps.history).clone();
56	        let mut new_cmds = (*deps.cmd_history).clone();
57	        let mut any = false;
58	        for line in lines {
59	            let trimmed = line.trim();
60	            if trimmed.is_empty() {
61	                continue;
62	            }
63	            any = true;
64	            new_cmds.push(trimmed.to_string());
65	            if trimmed == ":clear" {
66	                deps.session.borrow().clear();
67	                new_history.clear();
68	                continue;
69	            }
70	            // Saga 29 step 016: `:upload <name>` opens the file
71	            // picker programmatically. The browser only allows
72	            // `input.click()` while a user gesture is active --
73	            // the click here is in the synchronous chain of the
74	            // user's Enter keypress, which counts. After the
75	            // file picker resolves, `upload::make_upload_image`
76	            // (wired to the file input's onchange) reads the
77	            // pending name and binds the Result.
78	            if let Some(name) = parse_upload_command(trimmed) {
79	                if name.is_empty() {
80	                    new_history.push(upload_usage_entry(trimmed));
81	                    continue;
82	                }
83	                if !is_valid_identifier(&name) {
84	                    new_history.push(upload_bad_name_entry(trimmed, &name));
85	                    continue;
86	                }
87	                deps.pending_upload_name.set(Some(name.clone()));
88	                if let Some(input) = deps.upload_input_ref.cast::<HtmlInputElement>() {
89	                    input.set_value("");
90	                    input.click();
91	                    new_history.push(HistoryEntry {
92	                        input: trimmed.to_string(),
93	                        output: format!(
94	                            "Opened the file picker. Pick a photo to bind `{name}` as \
95	                             `Ok({{pixels: [1, 3, 64, 64], h: 64, w: 64}})`, or close \
96	                             the picker to bind `{name} = Err(\"cancelled\")`."
97	                        ),
98	                        is_error: false,
99	                        kind: EntryKind::Command,
100	                    });
101	                } else {
102	                    new_history.push(HistoryEntry {
103	                        input: trimmed.to_string(),
104	                        output: "error: upload file input not mounted (refresh and retry)"
105	                            .to_string(),
106	                        is_error: true,
107	                        kind: EntryKind::Command,
108	                    });
109	                }
110	                continue;
111	            }
112	            let entry = if trimmed == ":help" {
113	                HistoryEntry {
114	                    input: trimmed.to_string(),
115	                    output: help_text(),
116	                    is_error: false,
117	                    kind: EntryKind::Command,
118	                }
119	            } else {
120	                let result = deps.session.borrow().eval(trimmed);
121	                let is_error = result.starts_with("error:");
122	                HistoryEntry {
123	                    input: trimmed.to_string(),
124	                    output: result,
125	                    is_error,
126	                    kind: EntryKind::Command,
127	                }
128	            };
129	            new_history.push(entry);
130	        }
131	        if !any {
132	            return;
133	        }
134	        deps.history.set(new_history);
135	        deps.cmd_history.set(new_cmds);
136	        deps.cmd_index.set(None);
137	        deps.input_value.set(String::new());
138	    })
139	}
