141	/// Parse `:upload <name>` (or `:upload` with no arg). Returns
142	/// `Some(name)` if the line is the upload command, `None`
143	/// otherwise. An empty name means the user typed `:upload`
144	/// without a target.
145	fn parse_upload_command(line: &str) -> Option<String> {
146	    let rest = line.strip_prefix(":upload")?;
147	    Some(rest.trim().to_string())
148	}
