150	/// Bare-bones identifier check: alphanumeric + underscore, must
151	/// not start with a digit. Mirrors the parser's identifier
152	/// shape closely enough to reject obvious mistakes (e.g.
153	/// `:upload 1` or `:upload my photo`) before they hit the
154	/// session.
155	fn is_valid_identifier(s: &str) -> bool {
156	    let mut chars = s.chars();
157	    let Some(first) = chars.next() else {
158	        return false;
159	    };
160	    if !first.is_ascii_alphabetic() && first != '_' {
161	        return false;
162	    }
163	    chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
164	}
