/// Shared three-flavor history-entry pusher. The flavor
/// selects the title bar + tone; `body` is the rendered text
/// (success messages, cancel notes, or decode-error details).
fn push_entry(
    history: &UseStateHandle<Vec<HistoryEntry>>,
    flavor: EntryFlavor,
    name: &str,
    body: String,
) {
    let mut entries: Vec<HistoryEntry> = (**history).clone();
    entries.push(HistoryEntry {
        input: format!("{} ({name})", flavor.title()),
        output: body,
        is_error: matches!(flavor, EntryFlavor::Error),
        kind: EntryKind::Narration,
    });
    history.set(entries);
}

enum EntryFlavor {
    Success,
    Cancel,
    Error,
}

impl EntryFlavor {
    fn title(&self) -> &'static str {
        match self {
            Self::Success => "Image upload OK",
            Self::Cancel => "Image upload cancelled",
            Self::Error => "Image upload failed",
        }
    }
}

fn push_success(history: &UseStateHandle<Vec<HistoryEntry>>, name: &str, src_w: u32, src_h: u32) {
    let body = format!(
        "Your {src_w}x{src_h} photo was resized to {target_w}x{target_h} by the \
         browser's Canvas API and bound as \n\n\
         `{name} = Ok({{pixels: [1, 3, {target_h}, {target_w}], h: {target_h}, w: {target_w}}})`\n\n\
         Inspect: `is_ok({name})` (returns 1), `unwrap({name}).pixels` (the tensor), \
         `unwrap({name}).h` (height), or `svg(unwrap({name}).pixels, \"gallery\")` to view it.\n\n\
         Classify (after running \"Pets: cat vs dog (quick)\" or \"Pets: multi-head ViT (quick + viz)\"):\n\
         `img = unwrap({name}).pixels`\n\
         `predict_batch(classifier, take(apply(attn, reshape(apply(linear_p, reshape(patchify(img, 16), [16, 768])), [1, 16, 128])), 1, 0))` (0 = cat, 1 = dog)",
        target_w = TARGET_W,
        target_h = TARGET_H,
    );
    push_entry(history, EntryFlavor::Success, name, body);
}

fn push_cancel(history: &UseStateHandle<Vec<HistoryEntry>>, name: &str) {
    let body = format!(
        "You closed the file picker without choosing a photo. \
         `{name}` is now bound to `Err(\"cancelled\")`. \
         Check with `is_err({name})` or read the message with `err_message({name})`."
    );
    push_entry(history, EntryFlavor::Cancel, name, body);
}

fn push_error(history: &UseStateHandle<Vec<HistoryEntry>>, name: &str, msg: &str) {
    let body = format!(
        "{msg}\n\n`{name}` is bound to `Err(\"decode failed\")` -- inspect via `err_message({name})`."
    );
    push_entry(history, EntryFlavor::Error, name, body);
}

