    /// `message` is the user-visible error string (e.g.
    /// "cancelled", "decode failed: ...").
    pub fn bind_upload_result_err(&self, name: &str, message: &str) {
        self.env_mut()
            .set_result(name.into(), false, Value::Str(message.into()));
    }
}

