/// honored mid-batch.
pub fn make_submit_batch(deps: EvalDeps) -> Callback<Vec<String>> {
    Callback::from(move |lines: Vec<String>| {
        let mut new_history = (*deps.history).clone();
        let mut new_cmds = (*deps.cmd_history).clone();
        let mut any = false;
        for line in lines {
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }
            any = true;
            new_cmds.push(trimmed.to_string());
            if trimmed == ":clear" {
                deps.session.borrow().clear();
                new_history.clear();
                continue;
            }
            // Saga 29 step 016: `:upload <name>` opens the file
            // picker programmatically. The browser only allows
            // `input.click()` while a user gesture is active --
            // we are still in the synchronous chain of the
            // user's Enter keypress, which counts. After the
            // picker resolves, `upload::make_upload_image`
            // (wired to the file input's onchange) reads the
            // pending name and binds the Result.
            if let Some(name) = parse_upload_command(trimmed) {
                new_history.push(handle_upload_command(&deps, trimmed, &name));
                continue;
            }
            let entry = if trimmed == ":help" {
                HistoryEntry {
                    input: trimmed.to_string(),
                    output: help_text(),
                    is_error: false,
                    kind: EntryKind::Command,
                }
            } else {
                let result = deps.session.borrow().eval(trimmed);
                let is_error = result.starts_with("error:");
                HistoryEntry {
                    input: trimmed.to_string(),
                    output: result,
                    is_error,
                    kind: EntryKind::Command,
                }
            };
            new_history.push(entry);
        }
        if !any {
            return;
        }

