1	//! Client-side image upload via the browser's File / Image /
2	//! Canvas APIs. Saga 29 step 011 follow-up; step 016 rework.
3	//!
4	//! Two entry points share the same Canvas decode + resize
5	//! pipeline:
6	//!
7	//! 1. **Button-bound upload** (`make_upload_image`). Wired to
8	//!    a file `<input type="file">`'s `onchange` event. The
9	//!    chosen image binds under the name resolved from
10	//!    `pending_name`: `Some(name)` if a `:upload <name>` REPL
11	//!    command triggered the picker programmatically, else the
12	//!    default `"uploaded"` (the legacy button click).
13	//!
14	//! 2. **`:upload x` REPL command** (Saga 29 step 016). Routed
15	//!    in `handlers.rs::make_submit_batch`: setting
16	//!    `pending_name` to `Some("x")` and programmatically
17	//!    clicking the file input. The handler stays in the
18	//!    synchronous chain of the user's Enter keypress, so the
19	//!    browser accepts the `click()` as a user gesture.
20	//!
21	//! Either way, the uploaded image lands as a `Value::Result`
22	//! in the WASM session: `Ok({pixels: [1, 3, 64, 64], h: 64,
23	//! w: 64})` on success, `Err("cancelled")` if the picker is
24	//! dismissed, `Err("...")` for any decode/resize failure.
25	//! `:upload x` becomes the first in-tree consumer of the
26	//! `Value::Result` type shipped in Saga 29 step 012.
27	
28	use std::cell::RefCell;
29	use std::rc::Rc;
30	
31	use mlpl_wasm::WasmSession;
32	use wasm_bindgen::{JsCast, JsValue, closure::Closure};
33	use web_sys::{
34	    CanvasRenderingContext2d, Event, FileReader, HtmlCanvasElement, HtmlImageElement,
35	    HtmlInputElement, ImageData,
36	};
37	use yew::prelude::*;
38	
39	use crate::state::{EntryKind, HistoryEntry};
40	
41	const TARGET_H: u32 = 64;
42	const TARGET_W: u32 = 64;
43	const DEFAULT_NAME: &str = "uploaded";
44	
45	/// Caller-chosen variable name for the next upload binding.
46	/// `None` = the legacy button-click path (binds `"uploaded"`).
47	/// `Some(name)` = the `:upload <name>` REPL path.
48	pub type PendingUploadName = UseStateHandle<Option<String>>;
49	
50	pub fn make_upload_image(
51	    session: Rc<RefCell<WasmSession>>,
52	    history: UseStateHandle<Vec<HistoryEntry>>,
53	    pending_name: PendingUploadName,
54	) -> Callback<Event> {
55	    Callback::from(move |e: Event| {
56	        let target: HtmlInputElement = match e.target_dyn_into() {
57	            Some(t) => t,
58	            None => return,
59	        };
60	        let files = match target.files() {
61	            Some(f) => f,
62	            None => return,
63	        };
64	        if files.length() == 0 {
65	            return;
66	        }
67	        let file = match files.get(0) {
68	            Some(f) => f,
69	            None => return,
70	        };
71	        let name = pending_name
72	            .as_ref()
73	            .map_or_else(|| DEFAULT_NAME.to_string(), Clone::clone);
74	        pending_name.set(None);
75	        if let Err(err) = start_read(&file, &session, &history, &name) {
76	            session
77	                .borrow()
78	                .bind_upload_result_err(&name, "decode-init failed");
79	            push_error(&history, &name, &format!("{err:?}"));
80	        }
81	        // Reset so re-selecting the same file fires `change` again.
82	        target.set_value("");
83	    })
84	}
85	
86	/// Saga 29 step 016: cancel handler for the `<input type=file>`'s
87	/// `cancel` event. Wires `Err("cancelled")` under the pending
88	/// variable name (if any) so a `:upload x` command leaves
89	/// `x = Err("cancelled")` instead of an undefined variable.
90	///
91	/// Saga 29 step 017 guard: only fires when `pending_name` is
92	/// still `Some(_)`. The change-event handler clears
93	/// `pending_name` the moment it starts processing a real file
94	/// selection -- so if a stray `cancel` event arrives AFTER a
95	/// failed decode (some browsers fire both), it sees `None` and
96	/// skips, avoiding the "decoder failed but message says
97	/// cancelled" bug where a bad-format file appeared to bind
98	/// `Err("cancelled")`.
99	pub fn make_upload_cancel(
100	    session: Rc<RefCell<WasmSession>>,
101	    history: UseStateHandle<Vec<HistoryEntry>>,
102	    pending_name: PendingUploadName,
103	) -> Callback<Event> {
104	    Callback::from(move |_: Event| {
105	        let Some(name) = pending_name.as_ref().cloned() else {
106	            return;
107	        };
108	        pending_name.set(None);
109	        session.borrow().bind_upload_result_err(&name, "cancelled");
110	        push_cancel(&history, &name);
111	    })
112	}
113	
114	fn start_read(
115	    file: &web_sys::File,
116	    session: &Rc<RefCell<WasmSession>>,
117	    history: &UseStateHandle<Vec<HistoryEntry>>,
118	    name: &str,
119	) -> Result<(), JsValue> {
120	    let reader = FileReader::new()?;
121	    handlers::install_reader_onload(&reader, session, history, name);
122	    // Saga 29 step 017: FileReader.onerror fires when the file
123	    // is unreadable (zero bytes, permission issue, abort).
124	    handlers::install_reader_onerror(&reader, session, history, name);
125	    reader.read_as_data_url(file)?;
126	    Ok(())
127	}
128	
129	fn start_image_load(
130	    url: &str,
131	    session: &Rc<RefCell<WasmSession>>,
132	    history: &UseStateHandle<Vec<HistoryEntry>>,
133	    name: &str,
134	) -> Result<(), JsValue> {
135	    let img = HtmlImageElement::new()?;
136	    handlers::install_image_onload(&img, session, history, name, decode_image_to_session);
137	    // Saga 29 step 017: fires when the browser cannot decode
138	    // the data URL (e.g. a non-image file renamed to .jpg).
139	    // Without this handler the upload silently fails and a
140	    // stray cancel event later binds Err("cancelled"), which
141	    // misrepresents the actual failure.
142	    handlers::install_image_onerror(&img, session, history, name);
143	    img.set_src(url);
144	    Ok(())
145	}
146	
147	fn decode_image_to_session(
148	    img: &HtmlImageElement,
149	    session: &Rc<RefCell<WasmSession>>,
150	    history: &UseStateHandle<Vec<HistoryEntry>>,
151	    name: &str,
152	) -> Result<(), JsValue> {
153	    let src_w = img.natural_width();
154	    let src_h = img.natural_height();
155	    let document = web_sys::window()
156	        .ok_or_else(|| JsValue::from_str("no window"))?
157	        .document()
158	        .ok_or_else(|| JsValue::from_str("no document"))?;
159	    let canvas: HtmlCanvasElement = document
160	        .create_element("canvas")?
161	        .dyn_into()
162	        .map_err(|_| JsValue::from_str("not a canvas"))?;
163	    canvas.set_width(TARGET_W);
164	    canvas.set_height(TARGET_H);
165	    let ctx: CanvasRenderingContext2d = canvas
166	        .get_context("2d")?
167	        .ok_or_else(|| JsValue::from_str("no 2d context"))?
168	        .dyn_into()
169	        .map_err(|_| JsValue::from_str("not 2d context"))?;
170	    ctx.draw_image_with_html_image_element_and_dw_and_dh(
171	        img,
172	        0.0,
173	        0.0,
174	        f64::from(TARGET_W),
175	        f64::from(TARGET_H),
176	    )?;
177	    let imgdata: ImageData =
178	        ctx.get_image_data(0.0, 0.0, f64::from(TARGET_W), f64::from(TARGET_H))?;
179	    let bytes = imgdata.data();
180	    let h = TARGET_H as usize;
181	    let w = TARGET_W as usize;
182	    let mut chw = vec![0.0_f64; 3 * h * w];
183	    // bytes is RGBA in row-major HWC. Re-arrange to CHW and
184	    // normalize from u8 [0, 255] -> f64 [-1, 1].
185	    for c in 0..3 {
186	        for y in 0..h {
187	            for x in 0..w {
188	                let v = f64::from(bytes[(y * w + x) * 4 + c]);
189	                chw[c * h * w + y * w + x] = v / 127.5 - 1.0;
190	            }
191	        }
192	    }
193	    session
194	        .borrow()
195	        .bind_upload_result_ok(name, &chw, TARGET_H, TARGET_W)?;
196	    push_success(history, name, src_w, src_h);
197	    Ok(())
198	}
199	
200	// History-entry pushers + async-handler installers live in
201	// sub-modules so the success/cancel/error trio and the four
202	// install_*_on{load,error} helpers don't blow upload.rs past
203	// the sw-checklist per-module function-count budget.

