use mlpl_wasm::WasmSession;

#[test]
fn eval_scalar_arithmetic() {
    let session = WasmSession::new();
    assert_eq!(session.eval("1 + 2"), "3");
    assert_eq!(session.eval("3 * 4"), "12");
    assert_eq!(session.eval("10 / 3"), "3.3333333333333335");
}

#[test]
fn eval_array_ops() {
    let session = WasmSession::new();
    assert_eq!(session.eval("[1, 2, 3] * 10"), "10 20 30");
    assert_eq!(session.eval("[1, 2, 3] + [4, 5, 6]"), "5 7 9");
}

#[test]
fn eval_variable_persistence() {
    let session = WasmSession::new();
    assert_eq!(session.eval("x = 42"), "42");
    assert_eq!(session.eval("x + 1"), "43");
}

#[test]
fn eval_builtin_functions() {
    let session = WasmSession::new();
    assert_eq!(session.eval("iota(5)"), "0 1 2 3 4");
    assert_eq!(session.eval("shape([1,2,3])"), "3");
    assert_eq!(session.eval("reduce_add([1,2,3,4,5])"), "15");
}

#[test]
fn eval_error_returns_error_prefix() {
    let session = WasmSession::new();
    let result = session.eval("foo(1)");
    assert!(
        result.starts_with("error: "),
        "expected error prefix, got: {result}"
    );
}

#[test]
fn eval_parse_error() {
    let session = WasmSession::new();
    let result = session.eval("[1, 2,");
    assert!(
        result.starts_with("error: "),
        "expected error prefix, got: {result}"
    );
}

#[test]
fn eval_matrix_display() {
    let session = WasmSession::new();
    session.eval("x = iota(6)");
    let result = session.eval("reshape(x, [2, 3])");
    assert_eq!(result, "0 1 2\n3 4 5");
}

#[test]
fn eval_empty_input() {
    let session = WasmSession::new();
    assert_eq!(session.eval(""), "");
}

#[test]
fn eval_ml_functions() {
    let session = WasmSession::new();
    assert_eq!(session.eval("sigmoid(0)"), "0.5");
    assert_eq!(session.eval("mean([2, 4, 6])"), "4");
}

#[test]
fn separate_sessions_isolated() {
    let s1 = WasmSession::new();
    let s2 = WasmSession::new();
    s1.eval("x = 100");
    let result = s2.eval("x");
    assert!(
        result.starts_with("error: "),
        "sessions should be isolated, got: {result}"
    );
}

#[test]
fn eval_line_stateless() {
    assert_eq!(mlpl_wasm::eval_line("2 + 3"), "5");
    assert_eq!(mlpl_wasm::eval_line("[1,2] * 3"), "3 6");
}

#[test]
fn eval_string_literal_returns_string() {
    let session = WasmSession::new();
    assert_eq!(session.eval(r#""hello""#), "hello");
    assert_eq!(session.eval(r#""scatter""#), "scatter");
}

#[test]
fn eval_string_in_arithmetic_is_error() {
    let session = WasmSession::new();
    let result = session.eval(r#""x" + 1"#);
    assert!(result.starts_with("error: "));
}

#[test]
fn eval_svg_scatter_returns_svg_string() {
    let session = WasmSession::new();
    session.eval("pts = reshape([0,0,1,1,2,4], [3, 2])");
    let result = session.eval(r#"svg(pts, "scatter")"#);
    assert!(
        result.starts_with("<svg"),
        "expected svg output, got: {result}"
    );
    assert!(result.contains("<circle"), "expected circles in svg");
}

#[test]
fn eval_svg_unknown_type_is_error() {
    let session = WasmSession::new();
    let result = session.eval(r#"svg([[0,0],[1,1]], "rainbow")"#);
    assert!(result.starts_with("error: "), "got: {result}");
}

/// Saga 29 step 016: bind_upload_result_ok wraps the pixels +
/// dimensions in `Ok({pixels, h, w})` and binds under the
/// caller-chosen name. Verify the Result shape via the
/// existing accessor builtins.
#[test]
fn bind_upload_result_ok_round_trips_through_unwrap() {
    let session = WasmSession::new();
    let rgb = vec![0.1; 3 * 2 * 2]; // [3, 2, 2] f64 in [-1, 1]
    session
        .bind_upload_result_ok("img", &rgb, 2, 2)
        .expect("bind_upload_result_ok");
    // `is_ok(img)` returns scalar 1.0.
    let ok = session.eval("is_ok(img)");
    assert!(
        ok.starts_with("1") || ok == "1",
        "is_ok(img) should be 1, got: {ok}"
    );
    // `unwrap(img).h` reads the height scalar back.
    let h = session.eval("unwrap(img).h");
    assert!(h.starts_with("2"), "unwrap(img).h should be 2, got: {h}");
}

/// Saga 29 step 016: bind_upload_result_err binds an Err
/// wrapping a string message.
#[test]
fn bind_upload_result_err_round_trips_through_err_message() {
    let session = WasmSession::new();
    session.bind_upload_result_err("img", "cancelled");
    let is_err = session.eval("is_err(img)");
    assert!(
        is_err.starts_with("1") || is_err == "1",
        "is_err(img) should be 1, got: {is_err}"
    );
    let msg = session.eval("err_message(img)");
    assert!(
        msg.contains("cancelled"),
        "err_message(img) should contain 'cancelled', got: {msg}"
    );
}

