fn write_cell_grid(out: &mut String, x0: f64, y0: f64, plane: &[f64], rows: usize, cols: usize) {
    let (lo, hi) = data_range(plane);
    let span = if (hi - lo).abs() < f64::EPSILON {
        1.0
    } else {
