1	//! SVG diagram rendering for MLPL arrays.
2	
3	mod charts;
4	mod decision_boundary;
5	mod gallery;
6	mod heatmap;
7	mod heatmap_grid;
8	mod scatter;
9	
10	use std::fmt;
11	
12	use mlpl_array::DenseArray;
13	
14	pub use charts::{render_bar, render_line};
15	pub use decision_boundary::render_decision_boundary;
16	pub use gallery::render_gallery;
17	pub use heatmap::render_heatmap;
18	pub use heatmap_grid::render_heatmap_grid;
19	pub use scatter::{render_scatter, render_scatter3d};
20	
21	pub(crate) const W: f64 = 400.0;
22	pub(crate) const H: f64 = 300.0;
23	pub(crate) const PAD: f64 = 30.0;
24	
25	/// Plain min/max of a slice (no expansion when all equal).
26	pub(crate) fn data_range(values: &[f64]) -> (f64, f64) {
27	    let mut lo = f64::INFINITY;
28	    let mut hi = f64::NEG_INFINITY;
29	    for &v in values {
30	        if v < lo {
31	            lo = v;
32	        }
33	        if v > hi {
34	            hi = v;
35	        }
36	    }
37	    (lo, hi)
38	}
39	
40	/// Min/max of a slice, returning (lo-1, hi+1) when all values are equal
41	/// so the resulting range is non-zero.
42	pub(crate) fn bounds(values: &[f64]) -> (f64, f64) {
43	    let mut lo = f64::INFINITY;
44	    let mut hi = f64::NEG_INFINITY;
45	    for &v in values {
46	        if v < lo {
47	            lo = v;
48	        }
49	        if v > hi {
50	            hi = v;
51	        }
52	    }
53	    if lo == hi {
54	        (lo - 1.0, hi + 1.0)
55	    } else {
56	        (lo, hi)
57	    }
58	}
59	
60	/// Scale a data coordinate to plot pixels. `axis` 0 = x, 1 = y (flipped).
61	pub(crate) fn scale(v: f64, lo: f64, hi: f64, axis: u8) -> f64 {
62	    let t = (v - lo) / (hi - lo);
63	    if axis == 0 {
64	        PAD + t * (W - 2.0 * PAD)
65	    } else {
66	        H - PAD - t * (H - 2.0 * PAD)
67	    }
68	}
