70	/// Saga 29 step 019: write min/max scale labels at the
71	/// corners of the plot area. `xmin/xmax` flank the bottom
72	/// axis, `ymin/ymax` flank the left axis. Used by scatter,
73	/// line, and bar to make the plot self-explanatory without
74	/// a full tick-mark axis system.
75	pub(crate) fn write_corner_scale_labels(
76	    out: &mut String,
77	    xmin: f64,
78	    xmax: f64,
79	    ymin: f64,
80	    ymax: f64,
81	) {
82	    let x0 = PAD;
83	    let x1 = W - PAD;
84	    let y0 = PAD;
85	    let y1 = H - PAD;
86	    let fmt_label = |out: &mut String, x: f64, y: f64, anchor: &str, v: f64| {
87	        out.push_str(&format!(
88	            "<text x=\"{x:.1}\" y=\"{y:.1}\" fill=\"#cdd6f4\" \
89	             font-size=\"10\" font-family=\"monospace\" \
90	             text-anchor=\"{anchor}\">{v:.2}</text>"
91	        ));
92	    };
93	    // X-axis labels just below the bottom edge.
94	    fmt_label(out, x0, y1 + 11.0, "start", xmin);
95	    fmt_label(out, x1, y1 + 11.0, "end", xmax);
96	    // Y-axis labels just to the left of the left edge.
97	    fmt_label(out, x0 - 4.0, y1, "end", ymin);
98	    fmt_label(out, x0 - 4.0, y0 + 4.0, "end", ymax);
99	}
100	
101	pub(crate) fn write_svg_open(out: &mut String) {
102	    out.push_str(&format!(
103	        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 {W} {H}\" width=\"{W}\" height=\"{H}\">"
104	    ));
105	    out.push_str("<rect width=\"100%\" height=\"100%\" fill=\"#1e1e2e\"/>");
106	    let (x0, x1, y0, y1) = (PAD, W - PAD, PAD, H - PAD);
107	    out.push_str(&format!(
108	        "<line x1=\"{x0}\" y1=\"{y1}\" x2=\"{x1}\" y2=\"{y1}\" stroke=\"#45475a\" stroke-width=\"1\"/>"
109	    ));
110	    out.push_str(&format!(
111	        "<line x1=\"{x0}\" y1=\"{y0}\" x2=\"{x0}\" y2=\"{y1}\" stroke=\"#45475a\" stroke-width=\"1\"/>"
112	    ));
113	}
114	
115	pub(crate) fn write_svg_close(out: &mut String) {
116	    out.push_str("</svg>");
117	}
118	
119	/// Errors produced by SVG rendering.
120	#[derive(Clone, Debug, PartialEq)]
121	pub enum VizError {
122	    /// The data shape is not valid for the requested diagram.
123	    InvalidShape(String),
124	    /// The diagram type name is not recognized.
125	    UnknownType(String),
126	}
127	
128	impl fmt::Display for VizError {
129	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
130	        match self {
131	            Self::InvalidShape(s) => write!(f, "invalid shape for diagram: {s}"),
132	            Self::UnknownType(s) => write!(f, "unknown svg type: '{s}'"),
133	        }
134	    }
135	}
136	
137	impl std::error::Error for VizError {}
138	
139	/// Dispatch on a diagram type name. Returns the rendered SVG string.
140	pub fn render(data: &DenseArray, type_name: &str) -> Result<String, VizError> {
141	    render_with_aux(data, type_name, None)
142	}
143	
144	/// Dispatch on a diagram type name with an optional auxiliary array.
145	/// Diagrams that need extra inputs (e.g. `decision_boundary` needs the
146	/// training points) read them from `aux`.
147	pub fn render_with_aux(
148	    data: &DenseArray,
149	    type_name: &str,
150	    aux: Option<&DenseArray>,
151	) -> Result<String, VizError> {
152	    match type_name {
153	        "scatter" => render_scatter(data),
154	        "scatter3d" => render_scatter3d(data),
155	        "line" => render_line(data),
156	        "bar" => render_bar(data),
157	        "heatmap" => render_heatmap(data),
158	        "heatmap_grid" => render_heatmap_grid(data),
159	        "gallery" => render_gallery(data, aux),
160	        "decision_boundary" => {
161	            let training = aux.ok_or_else(|| {
162	                VizError::InvalidShape(
163	                    "decision_boundary requires a third argument (training points Nx3)".into(),
164	                )
165	            })?;
166	            render_decision_boundary(data, training)
167	        }
168	        other => Err(VizError::UnknownType(other.to_string())),
169	    }
170	}

