//! Small markdown-ish renderer for learning-path step
//! bodies and tutorial-lesson intros.
//!
//! Handles only the constructs the existing body strings
//! use: blank-line paragraphs, "- "/"* " unordered lists,
//! "1. "/"2. " ordered lists, inline `code`, **bold**, and
//! _emph_. Not a full markdown parser -- the goal is to
//! stop rendering multi-paragraph bodies as one wall of
//! run-on text in the path-step panel.

use yew::prelude::*;

/// Render `body` as a sequence of `<p>` / `<ul>` / `<ol>`
/// blocks. Adjacent bullet lines collapse into one list;
/// blank lines split paragraphs.
pub(crate) fn render_body(body: &str) -> Html {
    let blocks = parse_blocks(body);
    html! {
        <div class="path-body">
            { for blocks.into_iter().map(render_block) }
        </div>
    }
}

#[derive(Debug)]
enum Block {
    Paragraph(String),
    Unordered(Vec<String>),
    Ordered(Vec<String>),
}

fn parse_blocks(body: &str) -> Vec<Block> {
    let mut blocks: Vec<Block> = Vec::new();
    let mut para_lines: Vec<&str> = Vec::new();
    let mut ul_items: Vec<String> = Vec::new();
    let mut ol_items: Vec<String> = Vec::new();
    let flush_para = |para_lines: &mut Vec<&str>, blocks: &mut Vec<Block>| {
        if !para_lines.is_empty() {
            blocks.push(Block::Paragraph(para_lines.join(" ")));
            para_lines.clear();
        }
    };
    let flush_ul = |ul_items: &mut Vec<String>, blocks: &mut Vec<Block>| {
        if !ul_items.is_empty() {
            blocks.push(Block::Unordered(std::mem::take(ul_items)));
        }
    };
    let flush_ol = |ol_items: &mut Vec<String>, blocks: &mut Vec<Block>| {
        if !ol_items.is_empty() {
            blocks.push(Block::Ordered(std::mem::take(ol_items)));
        }
    };
    for line in body.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            flush_para(&mut para_lines, &mut blocks);
            flush_ul(&mut ul_items, &mut blocks);
            flush_ol(&mut ol_items, &mut blocks);
            continue;
        }
        if let Some(rest) = trimmed
            .strip_prefix("- ")
            .or_else(|| trimmed.strip_prefix("* "))
        {
            flush_para(&mut para_lines, &mut blocks);
            flush_ol(&mut ol_items, &mut blocks);
            ul_items.push(rest.to_string());
            continue;
        }
        if let Some(rest) = strip_ol_marker(trimmed) {
            flush_para(&mut para_lines, &mut blocks);
            flush_ul(&mut ul_items, &mut blocks);
            ol_items.push(rest.to_string());
            continue;
        }
        flush_ul(&mut ul_items, &mut blocks);
        flush_ol(&mut ol_items, &mut blocks);
        para_lines.push(trimmed);
    }
    flush_para(&mut para_lines, &mut blocks);
    flush_ul(&mut ul_items, &mut blocks);
    flush_ol(&mut ol_items, &mut blocks);
    blocks
}

/// Strip a leading ordered-list marker like "1. " or "12. ".
/// Returns the remainder of the line if the prefix matches.
fn strip_ol_marker(s: &str) -> Option<&str> {
    let mut chars = s.char_indices();
    let mut last_digit_end = 0;
    let mut saw_digit = false;
    for (i, c) in chars.by_ref() {
        if c.is_ascii_digit() {
            saw_digit = true;
            last_digit_end = i + 1;
        } else {
            break;
        }
    }
    if !saw_digit {
        return None;
    }
    let after_digits = &s[last_digit_end..];
    after_digits.strip_prefix(". ")
}

fn render_block(block: Block) -> Html {
    match block {
        Block::Paragraph(text) => html! {
            <p class="path-body-p">{ render_inline(&text) }</p>
        },
        Block::Unordered(items) => html! {
            <ul class="path-body-ul">
                { for items.into_iter().map(|t| html!{ <li>{ render_inline(&t) }</li> }) }
            </ul>
        },
        Block::Ordered(items) => html! {
            <ol class="path-body-ol">
                { for items.into_iter().map(|t| html!{ <li>{ render_inline(&t) }</li> }) }
            </ol>
        },
    }
}

/// Inline span-level rendering: backtick `code`, **bold**,
/// _emph_. Walks the string once and emits child nodes; any
/// unmatched delimiter is rendered as literal text.
fn render_inline(text: &str) -> Html {
    let parts = split_inline(text);
    html! { <>{ for parts.into_iter().map(render_span) }</> }
}

#[derive(Debug)]
enum Span {
    Text(String),
    Code(String),
    Bold(String),
    Emph(String),
}

fn render_span(span: Span) -> Html {
    match span {
        Span::Text(s) => html! { { s } },
        Span::Code(s) => html! { <code class="path-body-code">{ s }</code> },
        Span::Bold(s) => html! { <strong>{ s }</strong> },
        Span::Emph(s) => html! { <em>{ s }</em> },
    }
}

/// Tokenize inline span markers. Greedy + first-match wins;
/// no nesting (a span runs from delimiter to its mate, and
/// the inner text is emitted as a literal string).
fn split_inline(text: &str) -> Vec<Span> {
    let bytes = text.as_bytes();
    let mut spans: Vec<Span> = Vec::new();
    let mut buf = String::new();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if let Some((span, advance)) = try_match_span(bytes, i, c) {
            if !buf.is_empty() {
                spans.push(Span::Text(std::mem::take(&mut buf)));
            }
            spans.push(span);
            i += advance;
            continue;
        }
        buf.push(c as char);
        i += 1;
    }
    if !buf.is_empty() {
        spans.push(Span::Text(buf));
    }
    spans
}

fn try_match_span(bytes: &[u8], i: usize, c: u8) -> Option<(Span, usize)> {
    if c == b'`' {
        return match_until(bytes, i + 1, b'`').map(|(s, end)| (Span::Code(s), end - i));
    }
    if c == b'*' && i + 1 < bytes.len() && bytes[i + 1] == b'*' {
        return match_until_pair(bytes, i + 2, b'*', b'*').map(|(s, end)| (Span::Bold(s), end - i));
    }
    if c == b'_' {
        if let Some((s, end)) = match_until(bytes, i + 1, b'_') {
            return Some((Span::Emph(s), end - i));
        }
    }
    None
}

fn match_until(bytes: &[u8], start: usize, delim: u8) -> Option<(String, usize)> {
    let mut j = start;
    while j < bytes.len() {
        if bytes[j] == delim {
            let s = std::str::from_utf8(&bytes[start..j]).ok()?;
            return Some((s.to_string(), j + 1));
        }
        j += 1;
    }
    None
}

fn match_until_pair(bytes: &[u8], start: usize, d1: u8, d2: u8) -> Option<(String, usize)> {
    let mut j = start;
    while j + 1 < bytes.len() {
        if bytes[j] == d1 && bytes[j + 1] == d2 {
            let s = std::str::from_utf8(&bytes[start..j]).ok()?;
            return Some((s.to_string(), j + 2));
        }
        j += 1;
    }
    None
}

#[cfg(test)]
mod tests {
    use super::{Block, parse_blocks};

    #[test]
    fn empty_body_is_no_blocks() {
        assert!(parse_blocks("").is_empty());
        assert!(parse_blocks("   \n\n  ").is_empty());
    }

