#[derive(Default)]
struct BlockAcc<'a> {
    blocks: Vec<Block>,
    para_lines: Vec<&'a str>,
    ul_items: Vec<String>,
    ol_items: Vec<String>,
}

impl<'a> BlockAcc<'a> {
