fn render_block(block: Block) -> Html {
    match block {
        Block::Paragraph(text) => html! {
            <p class="path-body-p">{ render_inline(&text) }</p>
        },
        Block::Unordered(items) => html! {
            <ul class="path-body-ul">
                { for items.into_iter().map(|t| html!{ <li>{ render_inline(&t) }</li> }) }
            </ul>
        },
        Block::Ordered(items) => html! {
            <ol class="path-body-ol">
                { for items.into_iter().map(|t| html!{ <li>{ render_inline(&t) }</li> }) }
            </ol>
        },
    }
}

/// Inline span-level rendering: backtick `code`, **bold**,
/// _emph_. Walks the string once and emits child nodes; any
/// unmatched delimiter is rendered as literal text.
fn render_inline(text: &str) -> Html {
    let parts = split_inline(text);
    html! { <>{ for parts.into_iter().map(render_span) }</> }
}

#[derive(Debug)]
enum Span {
    Text(String),
    Code(String),
    Bold(String),
    Emph(String),
}

fn render_span(span: Span) -> Html {
    match span {
        Span::Text(s) => html! { { s } },
        Span::Code(s) => html! { <code class="path-body-code">{ s }</code> },
        Span::Bold(s) => html! { <strong>{ s }</strong> },
        Span::Emph(s) => html! { <em>{ s }</em> },
    }
}

/// Tokenize inline span markers. Greedy + first-match wins;
/// no nesting (a span runs from delimiter to its mate, and
/// the inner text is emitted as a literal string).
fn split_inline(text: &str) -> Vec<Span> {
    let bytes = text.as_bytes();
    let mut spans: Vec<Span> = Vec::new();
    let mut buf = String::new();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if let Some((span, advance)) = try_match_span(bytes, i, c) {
            if !buf.is_empty() {
                spans.push(Span::Text(std::mem::take(&mut buf)));
            }
            spans.push(span);
            i += advance;
            continue;
        }
        buf.push(c as char);
        i += 1;
    }
    if !buf.is_empty() {
        spans.push(Span::Text(buf));
    }
    spans
}

fn try_match_span(bytes: &[u8], i: usize, c: u8) -> Option<(Span, usize)> {
    if c == b'`' {
        return match_until(bytes, i + 1, b'`').map(|(s, end)| (Span::Code(s), end - i));
    }
    if c == b'*' && i + 1 < bytes.len() && bytes[i + 1] == b'*' {
        return match_until_pair(bytes, i + 2, b'*', b'*').map(|(s, end)| (Span::Bold(s), end - i));
    }
    if c == b'_'
        && let Some((s, end)) = match_until(bytes, i + 1, b'_')
    {
        return Some((Span::Emph(s), end - i));
    }
    None
}

fn match_until(bytes: &[u8], start: usize, delim: u8) -> Option<(String, usize)> {
    let mut j = start;
    while j < bytes.len() {
        if bytes[j] == delim {
            let s = std::str::from_utf8(&bytes[start..j]).ok()?;
            return Some((s.to_string(), j + 1));
        }
        j += 1;
    }
    None
}

fn match_until_pair(bytes: &[u8], start: usize, d1: u8, d2: u8) -> Option<(String, usize)> {
    let mut j = start;
    while j + 1 < bytes.len() {
        if bytes[j] == d1 && bytes[j + 1] == d2 {
            let s = std::str::from_utf8(&bytes[start..j]).ok()?;
            return Some((s.to_string(), j + 2));
        }
        j += 1;
    }
    None
}

#[cfg(test)]
mod tests {
    use super::{Block, parse_blocks};

    #[test]
    fn empty_body_is_no_blocks() {
        assert!(parse_blocks("").is_empty());
        assert!(parse_blocks("   \n\n  ").is_empty());
    }

    #[test]
    fn single_paragraph_is_one_block() {
        let blocks = parse_blocks("Hello world, this is one paragraph.");
        assert_eq!(blocks.len(), 1);
        assert!(matches!(&blocks[0], Block::Paragraph(s) if s.contains("Hello world")));
    }

    #[test]
    fn blank_line_splits_paragraphs() {
        let blocks = parse_blocks("first\n\nsecond\n\nthird");
        assert_eq!(blocks.len(), 3);
        for b in &blocks {
            assert!(matches!(b, Block::Paragraph(_)));
        }
    }

    #[test]
    fn bulleted_lines_collapse_to_one_list() {
        let blocks = parse_blocks("intro\n\n- a\n- b\n- c\n\nouttro");
        assert_eq!(blocks.len(), 3);
        assert!(matches!(&blocks[0], Block::Paragraph(_)));
        match &blocks[1] {
            Block::Unordered(items) => {
                assert_eq!(items.len(), 3);
                assert_eq!(items[0], "a");
                assert_eq!(items[1], "b");
                assert_eq!(items[2], "c");
            }
            other => panic!("expected Unordered, got {other:?}"),
        }
        assert!(matches!(&blocks[2], Block::Paragraph(_)));
    }

    #[test]
    fn star_bullet_marker_also_works() {
        let blocks = parse_blocks("* one\n* two");
        match &blocks[0] {
            Block::Unordered(items) => {
                assert_eq!(items, &vec!["one".to_string(), "two".to_string()])
            }
            other => panic!("expected Unordered, got {other:?}"),
        }
    }

    #[test]
    fn numbered_lines_become_ordered() {
        let blocks = parse_blocks("steps:\n\n1. first\n2. second\n3. third");
        assert_eq!(blocks.len(), 2);
        match &blocks[1] {
            Block::Ordered(items) => {
                let expected: Vec<String> =
                    vec!["first".to_string(), "second".to_string(), "third".to_string()];
                assert_eq!(items, &expected);
            }
            other => panic!("expected Ordered, got {other:?}"),
        }
    }

    #[test]
    fn paragraph_continues_across_single_newlines() {
        let blocks = parse_blocks("line one\nline two\nline three");
        assert_eq!(blocks.len(), 1);
        match &blocks[0] {
            Block::Paragraph(text) => {
                assert!(text.contains("line one"));
                assert!(text.contains("line two"));
                assert!(text.contains("line three"));
            }
            other => panic!("expected Paragraph, got {other:?}"),
        }
    }
}

