//! Small markdown-ish renderer for learning-path step
//! bodies and tutorial-lesson intros.
//!
//! Handles only the constructs the existing body strings
//! use: blank-line paragraphs, "- "/"* " unordered lists,
//! "1. "/"2. " ordered lists, inline `code`, **bold**, and
//! _emph_. Not a full markdown parser -- the goal is to
//! stop rendering multi-paragraph bodies as one wall of
//! run-on text in the path-step panel.

use yew::prelude::*;

/// Render `body` as a sequence of `<p>` / `<ul>` / `<ol>`
/// blocks. Adjacent bullet lines collapse into one list;
/// blank lines split paragraphs.
pub(crate) fn render_body(body: &str) -> Html {
    let blocks = parse_blocks(body);
    html! {
        <div class="path-body">
            { for blocks.into_iter().map(render_block) }
        </div>
    }
}

#[derive(Debug)]
enum Block {
    Paragraph(String),
    Unordered(Vec<String>),
    Ordered(Vec<String>),
}

fn parse_blocks(body: &str) -> Vec<Block> {
    let mut acc = BlockAcc::default();
    for line in body.lines() {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            acc.flush_all();
        } else if let Some(rest) = trimmed
            .strip_prefix("- ")
            .or_else(|| trimmed.strip_prefix("* "))
        {
            acc.push_ul(rest);
        } else if let Some(rest) = strip_ol_marker(trimmed) {
            acc.push_ol(rest);
        } else {
            acc.push_para_line(trimmed);
        }
    }
    acc.flush_all();
    acc.blocks
}

#[derive(Default)]
struct BlockAcc<'a> {
    blocks: Vec<Block>,
    para_lines: Vec<&'a str>,
    ul_items: Vec<String>,
    ol_items: Vec<String>,
}

impl<'a> BlockAcc<'a> {
    fn push_para_line(&mut self, line: &'a str) {
        self.flush_ul();
        self.flush_ol();
        self.para_lines.push(line);
    }
    fn push_ul(&mut self, text: &str) {
        self.flush_para();
        self.flush_ol();
        self.ul_items.push(text.to_string());
    }
    fn push_ol(&mut self, text: &str) {
        self.flush_para();
        self.flush_ul();
        self.ol_items.push(text.to_string());
    }
    fn flush_all(&mut self) {
        self.flush_para();
        self.flush_ul();
        self.flush_ol();
    }
    fn flush_para(&mut self) {
        if !self.para_lines.is_empty() {
            self.blocks.push(Block::Paragraph(self.para_lines.join(" ")));
            self.para_lines.clear();
        }
    }
    fn flush_ul(&mut self) {
        if !self.ul_items.is_empty() {
            self.blocks
                .push(Block::Unordered(std::mem::take(&mut self.ul_items)));
        }
    }
    fn flush_ol(&mut self) {
        if !self.ol_items.is_empty() {
            self.blocks
                .push(Block::Ordered(std::mem::take(&mut self.ol_items)));
        }
    }
}

/// Strip a leading ordered-list marker like "1. " or "12. ".
/// Returns the remainder of the line if the prefix matches.
fn strip_ol_marker(s: &str) -> Option<&str> {
    let mut chars = s.char_indices();
    let mut last_digit_end = 0;
    let mut saw_digit = false;
    for (i, c) in chars.by_ref() {
