    let Some(window) = web_sys::window() else {
        return;
    };
    let init = web_sys::CustomEventInit::new();
    init.set_detail(&wasm_bindgen::JsValue::from_str(term));
    init.set_bubbles(true);
    let Ok(event) =
        web_sys::CustomEvent::new_with_event_init_dict("mlpl-glossary-open", &init)
    else {
        return;
    };
    let _ = window.unchecked_into::<web_sys::EventTarget>().dispatch_event(&event);
}

