mod tests {
    use super::{Span, split};

    fn debug_spans(text: &str) -> Vec<String> {
        split(text)
            .into_iter()
            .map(|s| match s {
                Span::Text(t) => format!("T({t})"),
                Span::Code(t) => format!("C({t})"),
                Span::Bold(t) => format!("B({t})"),
                Span::Emph(t) => format!("E({t})"),
                Span::Glossary(t) => format!("G({t})"),
            })
            .collect()
    }

    #[test]
    fn plain_text_is_one_span() {
        assert_eq!(debug_spans("hello world"), vec!["T(hello world)"]);
    }

    #[test]
    fn glossary_sigil_creates_glossary_span() {
        assert_eq!(
            debug_spans("see [[take (builtin)]] for more"),
            vec!["T(see )", "G(take (builtin))", "T( for more)"]
        );
    }

    #[test]
    fn glossary_sigil_distinguishes_from_single_bracket() {
        // Single `[` is treated as literal text since [[ -> ]]
        // is the only bracket-form we recognize.
        assert_eq!(debug_spans("[not a link]"), vec!["T([not a link])"]);
    }

    #[test]
    fn unterminated_glossary_sigil_falls_back_to_text() {
        // `[[term` with no closing `]]` is left as literal text.
        let spans = debug_spans("[[unterminated");
        assert!(spans[0].starts_with("T("), "got: {spans:?}");
    }

