    fn code_span_does_not_swallow_glossary() {
        // Backticks come before brackets in the matcher, but
        // they only fire if the leading byte is a backtick.
        assert_eq!(
            debug_spans("`code` and [[Stack (tape op)]]"),
            vec!["C(code)", "T( and )", "G(Stack (tape op))"]
        );
    }
}

