//! Inline-span (backtick code, **bold**, _emph_) parsing
//! for the markdown-ish path-body renderer.

use wasm_bindgen::JsCast;
use yew::prelude::*;

#[derive(Debug)]
pub(crate) enum Span {
    Text(String),
    Code(String),
    Bold(String),
    Emph(String),
    /// Saga 29 step 024: `[[term]]` sigil. Renders as a
    /// clickable button that dispatches a window-level
    /// `mlpl-glossary-open` CustomEvent carrying the term.
    /// The top-level `GlossaryPopupHost` component listens
    /// for that event and opens the popup.
    Glossary(String),
}

pub(crate) fn render_span(span: Span) -> Html {
    match span {
        Span::Text(s) => html! { { s } },
        Span::Code(s) => html! { <code class="path-body-code">{ s }</code> },
        Span::Bold(s) => html! { <strong>{ s }</strong> },
        Span::Emph(s) => html! { <em>{ s }</em> },
        Span::Glossary(term) => {
            let term_for_click = term.clone();
            let onclick = Callback::from(move |e: MouseEvent| {
                e.prevent_default();
                dispatch_glossary_open(&term_for_click);
            });
            html! {
                <button class="glossary-link" type="button" {onclick} title={format!("Open glossary entry: {term}")}>
                    { term }
                </button>
            }
        }
    }
}

fn dispatch_glossary_open(term: &str) {
    let Some(window) = web_sys::window() else {
        return;
    };
    let init = web_sys::CustomEventInit::new();
    init.set_detail(&wasm_bindgen::JsValue::from_str(term));
    init.set_bubbles(true);
    let Ok(event) =
        web_sys::CustomEvent::new_with_event_init_dict("mlpl-glossary-open", &init)
    else {
        return;
    };
    let _ = window.unchecked_into::<web_sys::EventTarget>().dispatch_event(&event);
}

/// Tokenize inline span markers. Greedy + first-match wins;
/// no nesting (a span runs from delimiter to its mate, and
/// the inner text is emitted as a literal string).
pub(crate) fn split(text: &str) -> Vec<Span> {
    let bytes = text.as_bytes();
    let mut spans: Vec<Span> = Vec::new();
    let mut buf = String::new();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if let Some((span, advance)) = try_match_span(bytes, i, c) {
            if !buf.is_empty() {
                spans.push(Span::Text(std::mem::take(&mut buf)));
            }
            spans.push(span);
            i += advance;
            continue;
        }
        buf.push(c as char);
        i += 1;
    }
    if !buf.is_empty() {
        spans.push(Span::Text(buf));
    }
    spans
}

fn try_match_span(bytes: &[u8], i: usize, c: u8) -> Option<(Span, usize)> {
    if c == b'[' && i + 1 < bytes.len() && bytes[i + 1] == b'[' {
        return match_until_pair(bytes, i + 2, b']', b']')
            .map(|(s, end)| (Span::Glossary(s), end - i));
    }
    if c == b'`' {
        return match_until(bytes, i + 1, b'`').map(|(s, end)| (Span::Code(s), end - i));
    }
    if c == b'*' && i + 1 < bytes.len() && bytes[i + 1] == b'*' {
        return match_until_pair(bytes, i + 2, b'*', b'*').map(|(s, end)| (Span::Bold(s), end - i));
    }
    if c == b'_'
        && let Some((s, end)) = match_until(bytes, i + 1, b'_')
    {
        return Some((Span::Emph(s), end - i));
    }
    None
}

fn match_until(bytes: &[u8], start: usize, delim: u8) -> Option<(String, usize)> {
    let mut j = start;
    while j < bytes.len() {
        if bytes[j] == delim {
            let s = std::str::from_utf8(&bytes[start..j]).ok()?;
            return Some((s.to_string(), j + 1));
