        assert_eq!(spans.len(), 3);
        assert!(matches!(&spans[0], Span::Text(t) if t == "see "));
        assert!(matches!(&spans[1], Span::Glossary(t) if t == "take (builtin)"));
        assert!(matches!(&spans[2], Span::Text(t) if t == " for more"));
    }

